INSERT INTO `problem` (`id`, `title`, `description`, `input_description`, `output_description`, `sample_input`, `sample_output`, `difficulty`, `category_id`, `time_limit`, `memory_limit`, `template_code`, `answer_code`, `solution`, `status`, `submit_count`, `accept_count`) VALUES
(306, 'LRU缓存机制', '请你设计并实现一个满足 LRU（最近最少使用）缓存约束的数据结构。\n实现 LRUCache 类：\n  LRUCache(int capacity)  以正整数作为容量 capacity 初始化 LRU 缓存\n  int get(int key)        如果关键字 key 存在于缓存中，则返回关键字的值，否则返回 -1\n  void put(int key, int value)  如果关键字已存在则变更其值；不存在则插入。\n                                容量达到上限时，写入新数据前先淘汰最久未使用的关键字。\n要求 get 和 put 都以 O(1) 平均时间复杂度运行。', '第一行：缓存容量 capacity（正整数）\n第二行：操作条数 m\n接下来 m 行，每行一个操作，格式为 put key value 或 get key', '按顺序输出每次 get 操作的结果，每次一行；关键字不存在时输出 -1', '2\n7\nput 1 1\nput 2 2\nget 1\nput 3 3\nget 2\nput 4 4\nget 1\n', '1\n-1\n-1\n', 'MEDIUM', 1, 1000, 64, '', 'import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        final int cap = Integer.parseInt(sc.nextLine().trim());\n        int m = Integer.parseInt(sc.nextLine().trim());\n\n        // accessOrder=true 的 LinkedHashMap：每次 get/put 都会把该项挪到队尾，\n        // removeEldestEntry 返回 true 时就淘汰队头（最久未使用）的那一项。\n        LinkedHashMap<Integer, Integer> cache = new LinkedHashMap<Integer, Integer>(16, 0.75f, true) {\n            @Override\n            protected boolean removeEldestEntry(Map.Entry<Integer, Integer> eldest) {\n                return size() > cap;\n            }\n        };\n\n        StringBuilder sb = new StringBuilder();\n        for (int i = 0; i < m; i++) {\n            String[] parts = sc.nextLine().trim().split(\"\\\\s+\");\n            if (\"put\".equals(parts[0])) {\n                cache.put(Integer.parseInt(parts[1]), Integer.parseInt(parts[2]));\n            } else {\n                Integer v = cache.get(Integer.parseInt(parts[1]));\n                sb.append(v == null ? -1 : v).append(\"\\n\");\n            }\n        }\n        System.out.print(sb);\n    }\n}\n', '哈希表 + 双向链表是标准做法：哈希表给出 O(1) 定位，双向链表维护使用顺序。\n在 Java 里可以直接用 LinkedHashMap 的 accessOrder 模式（第三个构造参数传 true），它内部就是「哈希表 + 双向链表」，重写 removeEldestEntry 即可实现超容量淘汰。', 1, 1, 1),
(307, '有效的括号', '给定一个只包括 \'(\'，\')\'，\'{\'，\'}\'，\'[\'，\']\' 的字符串 s，判断字符串是否有效。\n有效字符串需满足：\n  1. 左括号必须用相同类型的右括号闭合\n  2. 左括号必须以正确的顺序闭合\n  3. 每个右括号都有一个对应的相同类型的左括号', '一行字符串 s（只含括号字符）', '输出 true 或 false', '()[]{}\n', 'true\n', 'EASY', 1, 1000, 64, '', 'import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String s = sc.nextLine().trim();\n        Deque<Character> stack = new ArrayDeque<>();\n        boolean ok = true;\n        for (char c : s.toCharArray()) {\n            if (c == \'(\' || c == \'[\' || c == \'{\') {\n                stack.push(c);\n            } else {\n                if (stack.isEmpty()) { ok = false; break; }\n                char top = stack.pop();\n                if ((c == \')\' && top != \'(\') || (c == \']\' && top != \'[\') || (c == \'}\' && top != \'{\')) {\n                    ok = false;\n                    break;\n                }\n            }\n        }\n        if (!stack.isEmpty()) ok = false;\n        System.out.println(ok);\n    }\n}\n', '用栈：遇到左括号就压栈；遇到右括号就看栈顶是不是配套的左括号，不配套或栈空则无效。扫描结束后栈必须为空，否则说明有左括号没闭合。', 1, 1, 1),
(308, '三数之和', '给你一个整数数组 nums，判断是否存在三元组 [nums[i], nums[j], nums[k]] 满足 i != j、i != k 且 j != k，同时还满足 nums[i] + nums[j] + nums[k] == 0。\n请返回所有和为 0 且不重复的三元组。（答案中不可以包含重复的三元组）', '第一行：数组长度 n\n第二行：n 个整数（空格分隔）', '输出所有符合条件的三元组，格式为 [[a,b,c],[d,e,f]]；没有则输出 []', '6\n-1 0 1 2 -1 -4\n', '[[-1,-1,2],[-1,0,1]]\n', 'MEDIUM', 1, 1000, 64, '', 'import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] nums = new int[n];\n        for (int i = 0; i < n; i++) nums[i] = sc.nextInt();\n        Arrays.sort(nums);\n\n        List<int[]> res = new ArrayList<>();\n        for (int i = 0; i < n - 2; i++) {\n            if (nums[i] > 0) break;\n            if (i > 0 && nums[i] == nums[i - 1]) continue;   // 跳过重复的固定位\n            int l = i + 1, r = n - 1;\n            while (l < r) {\n                int sum = nums[i] + nums[l] + nums[r];\n                if (sum == 0) {\n                    res.add(new int[]{nums[i], nums[l], nums[r]});\n                    while (l < r && nums[l] == nums[l + 1]) l++;\n                    while (l < r && nums[r] == nums[r - 1]) r--;\n                    l++;\n                    r--;\n                } else if (sum < 0) {\n                    l++;\n                } else {\n                    r--;\n                }\n            }\n        }\n\n        StringBuilder sb = new StringBuilder(\"[\");\n        for (int i = 0; i < res.size(); i++) {\n            if (i > 0) sb.append(\",\");\n            int[] t = res.get(i);\n            sb.append(\"[\").append(t[0]).append(\",\").append(t[1]).append(\",\").append(t[2]).append(\"]\");\n        }\n        sb.append(\"]\");\n        System.out.println(sb);\n    }\n}\n', '先排序，再固定第一个数，剩下两个数用左右双指针夹逼。\n关键在去重：固定位若与前一个相同就跳过；找到解后，左右指针都要跳过相邻的重复值。', 1, 1, 1),
(309, '环形链表', '给你一个链表的头节点 head，判断链表中是否有环。\n链表的节点值依次给出，并用 pos 表示「尾节点连到的节点下标」（从 0 开始）；pos = -1 表示没有环。', '第一行：节点个数 n\n第二行：n 个节点值（空格分隔）\n第三行：pos', '输出 true（有环）或 false（无环）', '4\n3 2 0 -4\n1\n', 'true\n', 'EASY', 1, 1000, 64, '', 'import java.util.*;\n\npublic class Main {\n    static class ListNode {\n        int val;\n        ListNode next;\n        ListNode(int v) { val = v; }\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] vals = new int[n];\n        for (int i = 0; i < n; i++) vals[i] = sc.nextInt();\n        int pos = sc.nextInt();\n\n        // 按数组建成链表，再把尾节点接到下标 pos 处形成环\n        ListNode[] nodes = new ListNode[n];\n        for (int i = 0; i < n; i++) nodes[i] = new ListNode(vals[i]);\n        for (int i = 0; i < n - 1; i++) nodes[i].next = nodes[i + 1];\n        if (pos >= 0 && pos < n) nodes[n - 1].next = nodes[pos];\n\n        // 快慢指针：有环的话两者一定会在环内相遇\n        ListNode slow = n > 0 ? nodes[0] : null;\n        ListNode fast = slow;\n        boolean hasCycle = false;\n        while (fast != null && fast.next != null) {\n            slow = slow.next;\n            fast = fast.next.next;\n            if (slow == fast) { hasCycle = true; break; }\n        }\n        System.out.println(hasCycle);\n    }\n}\n', '快慢指针（Floyd 判圈）：慢指针每次走一步，快指针每次走两步。如果链表有环，快指针会在环里追上慢指针；如果没有环，快指针会先走到 null。空间 O(1)，比用 HashSet 记录访问过的节点更优。', 1, 1, 1),
(310, '数组中的第K个最大元素', '给定整数数组 nums 和整数 k，请返回数组中第 k 个最大的元素。\n请注意，你需要找的是数组排序后的第 k 个最大的元素，而不是第 k 个不同的元素。', '第一行：数组长度 n 和整数 k（空格分隔）\n第二行：n 个整数', '输出第 k 个最大的元素', '6 2\n3 2 1 5 6 4\n', '5\n', 'MEDIUM', 1, 1000, 64, '', 'import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int k = sc.nextInt();\n        int[] nums = new int[n];\n        for (int i = 0; i < n; i++) nums[i] = sc.nextInt();\n\n        // 维护一个容量为 k 的小顶堆，堆顶就是第 k 大\n        PriorityQueue<Integer> heap = new PriorityQueue<>();\n        for (int v : nums) {\n            heap.offer(v);\n            if (heap.size() > k) heap.poll();\n        }\n        System.out.println(heap.peek());\n    }\n}\n', '两种思路：\n1. 小顶堆：遍历数组，堆大小超过 k 就弹出堆顶，最后堆顶即第 k 大。时间 O(n log k)，适合数据量大而 k 小的场景。\n2. 快速选择（快排的 partition）：平均 O(n)，但最坏 O(n²)。\n本题解用小顶堆，稳定且好写。', 1, 1, 1),
(311, '寻找峰值', '峰值元素是指其值严格大于左右相邻值的元素。\n给你一个整数数组 nums，找到峰值元素并返回其索引。数组可能包含多个峰值，返回任意一个即可。\n可以假设 nums[-1] = nums[n] = -∞，也就是说数组两端的元素只要大于它唯一的邻居就算峰值。\n要求算法时间复杂度为 O(log n)。', '第一行：数组长度 n\n第二行：n 个整数', '输出任意一个峰值元素的下标', '4\n1 2 3 1\n', '2\n', 'MEDIUM', 1, 1000, 64, '', 'import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] nums = new int[n];\n        for (int i = 0; i < n; i++) nums[i] = sc.nextInt();\n\n        // 二分：比较中点与右邻居，往「上坡」的方向收缩，一定能走到某个峰值\n        int lo = 0, hi = n - 1;\n        while (lo < hi) {\n            int mid = lo + (hi - lo) / 2;\n            if (nums[mid] > nums[mid + 1]) {\n                hi = mid;\n            } else {\n                lo = mid + 1;\n            }\n        }\n        System.out.println(lo);\n    }\n}\n', '二分查找。每次比较 nums[mid] 和 nums[mid+1]：\n  如果 nums[mid] > nums[mid+1]，说明左侧（含 mid）必有峰值，令 hi = mid；\n  否则右侧必有峰值，令 lo = mid + 1。\n循环结束时 lo == hi 就是峰值下标，复杂度 O(log n)。', 1, 1, 1),
(312, '最大子序和', '给你一个整数数组 nums，请你找出一个具有最大和的连续子数组（子数组最少包含一个元素），返回其最大和。', '第一行：数组长度 n\n第二行：n 个整数', '输出最大子数组的和', '9\n-2 1 -3 4 -1 2 1 -5 4\n', '6\n', 'MEDIUM', 1, 1000, 64, '', 'import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] nums = new int[n];\n        for (int i = 0; i < n; i++) nums[i] = sc.nextInt();\n\n        // Kadane：cur 表示「以当前元素结尾的最大子数组和」\n        int cur = nums[0], best = nums[0];\n        for (int i = 1; i < n; i++) {\n            cur = Math.max(nums[i], cur + nums[i]);\n            best = Math.max(best, cur);\n        }\n        System.out.println(best);\n    }\n}\n', 'Kadane 算法：设 cur 为「必须以当前位置结尾」的最大子数组和，则\n  cur = max(nums[i], cur + nums[i])   —— 要么从当前元素重新开始，要么接上前面的\n答案就是所有 cur 里的最大值。时间 O(n)，空间 O(1)。', 1, 1, 1),
(313, '盛最多水的容器', '给定一个长度为 n 的整数数组 height。有 n 条垂线，第 i 条线的两个端点是 (i, 0) 和 (i, height[i])。\n找出其中的两条线，使得它们与 x 轴共同构成的容器可以容纳最多的水，返回容器可以储存的最大水量。\n注意：你不能倾斜容器。', '第一行：数组长度 n\n第二行：n 个整数（垂线高度）', '输出最大水量', '9\n1 8 6 2 5 4 8 3 7\n', '49\n', 'MEDIUM', 1, 1000, 64, '', 'import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] h = new int[n];\n        for (int i = 0; i < n; i++) h[i] = sc.nextInt();\n\n        // 双指针从两端往中间收：面积 = 较矮的那条边 × 宽度\n        int l = 0, r = n - 1, best = 0;\n        while (l < r) {\n            int area = Math.min(h[l], h[r]) * (r - l);\n            best = Math.max(best, area);\n            // 移动较矮的一侧才有机会变大；移动高的一侧宽度变小、高度还受矮边限制，只会更差\n            if (h[l] < h[r]) l++;\n            else r--;\n        }\n        System.out.println(best);\n    }\n}\n', '双指针。容器面积 = min(左高, 右高) × 两指针距离。\n移动策略：每次都移动较矮的那一侧。因为宽度必然减小，只有把矮边换掉，高度才可能提升；移动高边的话高度受矮边限制不会变好。\n时间 O(n)，空间 O(1)。', 1, 1, 1),
(314, '合并区间', '以数组 intervals 表示若干个区间的集合，其中单个区间为 intervals[i] = [starti, endi]。\n请你合并所有重叠的区间，并返回一个不重叠的区间数组，该数组需恰好覆盖输入中的所有区间。', '第一行：区间个数 n\n接下来 n 行，每行两个整数，表示区间的起点和终点', '输出合并后的区间数组，格式为 [[a,b],[c,d]]', '4\n1 3\n2 6\n8 10\n15 18\n', '[[1,6],[8,10],[15,18]]\n', 'MEDIUM', 1, 1000, 64, '', 'import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[][] intervals = new int[n][2];\n        for (int i = 0; i < n; i++) {\n            intervals[i][0] = sc.nextInt();\n            intervals[i][1] = sc.nextInt();\n        }\n\n        // 按左端点排序后，重叠区间必然相邻\n        Arrays.sort(intervals, (a, b) -> a[0] - b[0]);\n\n        List<int[]> merged = new ArrayList<>();\n        for (int[] cur : intervals) {\n            if (merged.isEmpty() || merged.get(merged.size() - 1)[1] < cur[0]) {\n                merged.add(new int[]{cur[0], cur[1]});\n            } else {\n                int[] last = merged.get(merged.size() - 1);\n                last[1] = Math.max(last[1], cur[1]);\n            }\n        }\n\n        StringBuilder sb = new StringBuilder(\"[\");\n        for (int i = 0; i < merged.size(); i++) {\n            if (i > 0) sb.append(\",\");\n            sb.append(\"[\").append(merged.get(i)[0]).append(\",\").append(merged.get(i)[1]).append(\"]\");\n        }\n        sb.append(\"]\");\n        System.out.println(sb);\n    }\n}\n', '按左端点排序，然后一次线性扫描：\n  如果当前区间的左端点大于结果里最后一个区间的右端点，说明不重叠，直接加入；\n  否则与最后一个区间合并（右端点取两者的较大值）。\n时间 O(n log n)（排序），空间 O(n)。', 1, 1, 1),
(315, '编辑距离', '给你两个单词 word1 和 word2，请返回将 word1 转换成 word2 所使用的最少操作数。\n你可以对一个单词进行如下三种操作：插入一个字符、删除一个字符、替换一个字符。', '第一行：单词 word1\n第二行：单词 word2', '输出最少操作数', 'horse\nros\n', '3\n', 'HARD', 1, 1000, 64, '', 'import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String a = sc.nextLine().trim();\n        String b = sc.nextLine().trim();\n\n        int n = a.length(), m = b.length();\n        // dp[i][j]：a 的前 i 个字符转成 b 的前 j 个字符所需的最少操作数\n        int[][] dp = new int[n + 1][m + 1];\n        for (int i = 0; i <= n; i++) dp[i][0] = i;   // 全删掉\n        for (int j = 0; j <= m; j++) dp[0][j] = j;   // 全插入\n\n        for (int i = 1; i <= n; i++) {\n            for (int j = 1; j <= m; j++) {\n                if (a.charAt(i - 1) == b.charAt(j - 1)) {\n                    dp[i][j] = dp[i - 1][j - 1];\n                } else {\n                    dp[i][j] = 1 + Math.min(dp[i - 1][j - 1],\n                                    Math.min(dp[i - 1][j], dp[i][j - 1]));\n                }\n            }\n        }\n        System.out.println(dp[n][m]);\n    }\n}\n', '经典二维 DP。dp[i][j] 表示 word1 前 i 个字符转成 word2 前 j 个字符的最少操作数。\n  字符相同时：dp[i][j] = dp[i-1][j-1]（不用操作）\n  不同时：dp[i][j] = 1 + min(替换 dp[i-1][j-1], 删除 dp[i-1][j], 插入 dp[i][j-1])\n边界 dp[i][0] = i、dp[0][j] = j。时间 O(nm)。', 1, 1, 1),
(316, '打家劫舍', '你是一个专业的小偷，计划偷窃沿街的房屋。每间房内都藏有一定的现金，影响你偷窃的唯一制约因素就是相邻的房屋装有相互连通的防盗系统，如果两间相邻的房屋在同一晚上被小偷闯入，系统会自动报警。\n给定一个代表每个房屋存放金额的非负整数数组，计算你不触动警报装置的情况下，一夜之内能够偷窃到的最高金额。', '第一行：房屋数量 n\n第二行：n 个非负整数', '输出能偷到的最高金额', '4\n1 2 3 1\n', '4\n', 'MEDIUM', 13, 1000, 64, '', 'import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] nums = new int[n];\n        for (int i = 0; i < n; i++) nums[i] = sc.nextInt();\n\n        // prev2 表示「隔一家」的最大收益，prev1 表示「到上一家」的最大收益\n        int prev2 = 0, prev1 = 0;\n        for (int v : nums) {\n            int cur = Math.max(prev1, prev2 + v);   // 不偷这家 / 偷这家（那上一家就不能偷）\n            prev2 = prev1;\n            prev1 = cur;\n        }\n        System.out.println(prev1);\n    }\n}\n', '动态规划：dp[i] = max(dp[i-1], dp[i-2] + nums[i])。\n含义是「到第 i 家为止能偷到的最大金额」，要么不偷第 i 家（沿用 dp[i-1]），要么偷第 i 家（那第 i-1 家必须跳过）。\n由于只依赖前两项，用两个滚动变量即可把空间压到 O(1)。', 1, 1, 1),
(317, '下一个排列', '整数数组的一个排列就是将其所有成员以序列或线性顺序排列。\n给你一个整数数组 nums，找出 nums 的下一个排列。\n必须原地修改，只允许使用额外常数空间。\n如果不存在下一个更大的排列，则将 nums 重新排列为最小的排列（即升序排列）。', '第一行：数组长度 n\n第二行：n 个整数', '输出下一个排列（各数字用空格分隔）', '3\n1 2 3\n', '1 3 2\n', 'MEDIUM', 1, 1000, 64, '', 'import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] nums = new int[n];\n        for (int i = 0; i < n; i++) nums[i] = sc.nextInt();\n\n        // 1. 从右往左找第一个「升序」的位置 i（nums[i] < nums[i+1]）\n        int i = n - 2;\n        while (i >= 0 && nums[i] >= nums[i + 1]) i--;\n\n        if (i >= 0) {\n            // 2. 在 i 右边从右往左找第一个比 nums[i] 大的数，交换\n            int j = n - 1;\n            while (nums[j] <= nums[i]) j--;\n            int t = nums[i]; nums[i] = nums[j]; nums[j] = t;\n        }\n        // 3. 把 i 之后的区间反转成升序（它原本是降序的）\n        for (int l = i + 1, r = n - 1; l < r; l++, r--) {\n            int t = nums[l]; nums[l] = nums[r]; nums[r] = t;\n        }\n\n        StringBuilder sb = new StringBuilder();\n        for (int k = 0; k < n; k++) {\n            if (k > 0) sb.append(\" \");\n            sb.append(nums[k]);\n        }\n        System.out.println(sb);\n    }\n}\n', '三步走：\n1. 从右往左找到第一个 nums[i] < nums[i+1] 的位置 i —— 这是能变大的最靠右的位置；\n2. 在 i 右侧从右往左找第一个大于 nums[i] 的数，与 nums[i] 交换（保证变大幅度最小）；\n3. 把 i 右侧区间反转成升序（该区间原来是降序，反转即得到最小后缀）。\n若找不到 i，说明整个数组降序，直接反转全体得到最小排列。', 1, 1, 1),
(318, '最长公共前缀', '编写一个函数来查找字符串数组中的最长公共前缀。\n如果不存在公共前缀，返回空字符串 \"\"。', '第一行：字符串个数 n\n接下来 n 行，每行一个字符串', '输出最长公共前缀（不存在则输出空行）', '3\nflower\nflow\nflight\n', 'fl\n', 'EASY', 1, 1000, 64, '', 'import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = Integer.parseInt(sc.nextLine().trim());\n        String[] strs = new String[n];\n        for (int i = 0; i < n; i++) strs[i] = sc.nextLine().trim();\n\n        // 以第一个字符串为基准，逐位和其他字符串比较\n        String base = strs[0];\n        int len = base.length();\n        for (int i = 1; i < n; i++) {\n            int j = 0;\n            while (j < len && j < strs[i].length() && base.charAt(j) == strs[i].charAt(j)) j++;\n            len = j;\n            if (len == 0) break;\n        }\n        System.out.println(base.substring(0, len));\n    }\n}\n', '纵向扫描：拿第一个字符串当基准，逐位和其余字符串比较，一旦某个位置不匹配就把公共长度截断到该位置。\n也可以横向两两求公共前缀，复杂度相同。', 1, 1, 1),
(319, '用栈实现队列', '请你仅使用两个栈实现先入先出队列。队列应当支持一般队列支持的所有操作：\n  push(x)  —— 将元素 x 推到队列的末尾\n  pop()    —— 从队列开头移除并返回元素\n  peek()   —— 返回队列开头的元素\n  empty()  —— 如果队列为空，返回 true，否则返回 false', '第一行：操作条数 m\n接下来 m 行，每行一个操作：push x / pop / peek / empty', '按顺序输出 pop、peek、empty 三种操作的结果，每次一行', '6\npush 1\npush 2\npeek\npop\nempty\npop\n', '1\n1\nfalse\n2\n', 'EASY', 2, 1000, 64, '', 'import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int m = Integer.parseInt(sc.nextLine().trim());\n\n        // in 负责入队，out 负责出队；out 空了就把 in 整体倒过来\n        Deque<Integer> in = new ArrayDeque<>();\n        Deque<Integer> out = new ArrayDeque<>();\n\n        StringBuilder sb = new StringBuilder();\n        for (int i = 0; i < m; i++) {\n            String[] parts = sc.nextLine().trim().split(\"\\\\s+\");\n            String op = parts[0];\n            if (\"push\".equals(op)) {\n                in.push(Integer.parseInt(parts[1]));\n            } else if (\"pop\".equals(op)) {\n                move(in, out);\n                sb.append(out.pop()).append(\"\\n\");\n            } else if (\"peek\".equals(op)) {\n                move(in, out);\n                sb.append(out.peek()).append(\"\\n\");\n            } else {\n                sb.append(in.isEmpty() && out.isEmpty()).append(\"\\n\");\n            }\n        }\n        System.out.print(sb);\n    }\n\n    static void move(Deque<Integer> in, Deque<Integer> out) {\n        if (out.isEmpty()) {\n            while (!in.isEmpty()) out.push(in.pop());\n        }\n    }\n}\n', '两个栈分工：in 栈负责 push，out 栈负责 pop/peek。\n当 out 为空时，把 in 里的元素依次弹出压入 out —— 顺序就被反过来了，此时 out 的栈顶就是队头。\n每个元素最多被搬运一次，所以均摊时间复杂度是 O(1)。', 1, 1, 1),
(320, '最小栈', '设计一个支持 push、pop、top 操作，并能在常数时间内检索到最小元素的栈。\n实现 MinStack 类：\n  push(val)  —— 将元素 val 推入栈中\n  pop()      —— 删除栈顶元素\n  top()      —— 获取栈顶元素\n  getMin()   —— 检索栈中的最小元素', '第一行：操作条数 m\n接下来 m 行，每行一个操作：push val / pop / top / getMin', '按顺序输出 top 和 getMin 的结果，每次一行', '6\npush -2\npush 0\npush -3\ngetMin\npop\ngetMin\n', '-3\n-2\n', 'MEDIUM', 2, 1000, 64, '', 'import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int m = Integer.parseInt(sc.nextLine().trim());\n\n        Deque<Integer> stack = new ArrayDeque<>();\n        // 辅助栈：栈顶始终是当前栈内最小值\n        Deque<Integer> minStack = new ArrayDeque<>();\n\n        StringBuilder sb = new StringBuilder();\n        for (int i = 0; i < m; i++) {\n            String[] parts = sc.nextLine().trim().split(\"\\\\s+\");\n            String op = parts[0];\n            if (\"push\".equals(op)) {\n                int v = Integer.parseInt(parts[1]);\n                stack.push(v);\n                minStack.push(minStack.isEmpty() ? v : Math.min(v, minStack.peek()));\n            } else if (\"pop\".equals(op)) {\n                stack.pop();\n                minStack.pop();\n            } else if (\"top\".equals(op)) {\n                sb.append(stack.peek()).append(\"\\n\");\n            } else {\n                sb.append(minStack.peek()).append(\"\\n\");\n            }\n        }\n        System.out.print(sb);\n    }\n}\n', '用一个辅助栈同步记录「当前最小值」：\npush 时把 min(新值, 辅助栈栈顶) 也压入辅助栈；pop 时两个栈一起弹。\n这样辅助栈栈顶永远是当前主栈里的最小值，getMin 就是 O(1)。', 1, 1, 1),
(321, '二叉树的最近公共祖先', '给定一个二叉树, 找到该树中两个指定节点的最近公共祖先。\n最近公共祖先的定义为：对于有根树 T 的两个节点 p、q，最近公共祖先表示为一个节点 x，满足 x 是 p、q 的祖先且 x 的深度尽可能大（一个节点也可以是它自己的祖先）。\n题目保证所有节点的值互不相同，且 p、q 均存在于树中。', '第一行：二叉树的层序数组（null 表示空节点）\n第二行：节点 p 的值\n第三行：节点 q 的值', '输出最近公共祖先节点的值', '[3,5,1,6,2,0,8,null,null,7,4]\n5\n1\n', '3\n', 'MEDIUM', 11, 1000, 64, '', 'import java.util.*;\n\npublic class Main {\n    static class TreeNode {\n        int val;\n        TreeNode left, right;\n        TreeNode(int v) { val = v; }\n    }\n\n    static TreeNode build(String line) {\n        line = line.trim();\n        if (line.startsWith(\"[\")) line = line.substring(1, line.length() - 1);\n        if (line.isEmpty()) return null;\n        String[] parts = line.split(\",\");\n        TreeNode root = new TreeNode(Integer.parseInt(parts[0].trim()));\n        java.util.Queue<TreeNode> q = new java.util.LinkedList<>();\n        q.offer(root);\n        int i = 1;\n        while (!q.isEmpty() && i < parts.length) {\n            TreeNode cur = q.poll();\n            String l = parts[i++].trim();\n            if (!\"null\".equals(l)) {\n                cur.left = new TreeNode(Integer.parseInt(l));\n                q.offer(cur.left);\n            }\n            if (i < parts.length) {\n                String r = parts[i++].trim();\n                if (!\"null\".equals(r)) {\n                    cur.right = new TreeNode(Integer.parseInt(r));\n                    q.offer(cur.right);\n                }\n            }\n        }\n        return root;\n    }\n\n    static String serialize(TreeNode root) {\n        if (root == null) return \"[]\";\n        java.util.List<String> out = new java.util.ArrayList<>();\n        java.util.Queue<TreeNode> q = new java.util.LinkedList<>();\n        q.offer(root);\n        while (!q.isEmpty()) {\n            TreeNode cur = q.poll();\n            if (cur == null) { out.add(\"null\"); continue; }\n            out.add(String.valueOf(cur.val));\n            q.offer(cur.left);\n            q.offer(cur.right);\n        }\n        while (!out.isEmpty() && \"null\".equals(out.get(out.size() - 1))) out.remove(out.size() - 1);\n        return \"[\" + String.join(\",\", out) + \"]\";\n    }\n\n    static TreeNode find(TreeNode root, int v) {\n        if (root == null) return null;\n        if (root.val == v) return root;\n        TreeNode l = find(root.left, v);\n        return l != null ? l : find(root.right, v);\n    }\n\n    static TreeNode lca(TreeNode root, TreeNode p, TreeNode q) {\n        if (root == null || root == p || root == q) return root;\n        TreeNode l = lca(root.left, p, q);\n        TreeNode r = lca(root.right, p, q);\n        if (l != null && r != null) return root;   // 两边各找到一个 → 当前节点就是分叉点\n        return l != null ? l : r;\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        TreeNode root = build(sc.nextLine());\n        TreeNode p = find(root, Integer.parseInt(sc.nextLine().trim()));\n        TreeNode q = find(root, Integer.parseInt(sc.nextLine().trim()));\n        System.out.println(lca(root, p, q).val);\n    }\n}\n', '后序遍历递归：\n  如果当前节点是 null、或者就是 p / q，直接返回当前节点；\n  分别到左右子树里找 p 和 q：\n    两边都找到了 → 说明 p、q 分布在当前节点两侧，当前节点就是最近公共祖先；\n    只有一边找到 → 返回那一边的结果，说明两个目标都在同一侧。\n时间 O(n)。', 1, 1, 1),
(322, '验证二叉搜索树', '给你一个二叉树的根节点 root，判断其是否是一个有效的二叉搜索树。\n有效二叉搜索树定义如下：\n  节点的左子树只包含小于当前节点的数\n  节点的右子树只包含大于当前节点的数\n  所有左子树和右子树自身必须也是二叉搜索树', '一行：二叉树的层序数组（null 表示空节点）', '输出 true 或 false', '[2,1,3]\n', 'true\n', 'MEDIUM', 11, 1000, 64, '', 'import java.util.*;\n\npublic class Main {\n    static class TreeNode {\n        int val;\n        TreeNode left, right;\n        TreeNode(int v) { val = v; }\n    }\n\n    static TreeNode build(String line) {\n        line = line.trim();\n        if (line.startsWith(\"[\")) line = line.substring(1, line.length() - 1);\n        if (line.isEmpty()) return null;\n        String[] parts = line.split(\",\");\n        TreeNode root = new TreeNode(Integer.parseInt(parts[0].trim()));\n        java.util.Queue<TreeNode> q = new java.util.LinkedList<>();\n        q.offer(root);\n        int i = 1;\n        while (!q.isEmpty() && i < parts.length) {\n            TreeNode cur = q.poll();\n            String l = parts[i++].trim();\n            if (!\"null\".equals(l)) {\n                cur.left = new TreeNode(Integer.parseInt(l));\n                q.offer(cur.left);\n            }\n            if (i < parts.length) {\n                String r = parts[i++].trim();\n                if (!\"null\".equals(r)) {\n                    cur.right = new TreeNode(Integer.parseInt(r));\n                    q.offer(cur.right);\n                }\n            }\n        }\n        return root;\n    }\n\n    static String serialize(TreeNode root) {\n        if (root == null) return \"[]\";\n        java.util.List<String> out = new java.util.ArrayList<>();\n        java.util.Queue<TreeNode> q = new java.util.LinkedList<>();\n        q.offer(root);\n        while (!q.isEmpty()) {\n            TreeNode cur = q.poll();\n            if (cur == null) { out.add(\"null\"); continue; }\n            out.add(String.valueOf(cur.val));\n            q.offer(cur.left);\n            q.offer(cur.right);\n        }\n        while (!out.isEmpty() && \"null\".equals(out.get(out.size() - 1))) out.remove(out.size() - 1);\n        return \"[\" + String.join(\",\", out) + \"]\";\n    }\n\n    // 中序遍历：如果是合法 BST，结果必然是严格递增的\n    static boolean valid = true;\n    static TreeNode prev = null;\n\n    static void inorder(TreeNode node) {\n        if (node == null || !valid) return;\n        inorder(node.left);\n        if (prev != null && prev.val >= node.val) valid = false;\n        prev = node;\n        inorder(node.right);\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        TreeNode root = build(sc.nextLine());\n        inorder(root);\n        System.out.println(valid);\n    }\n}\n', 'BST 的中序遍历结果一定是严格递增序列，所以中序遍历一遍、检查每个节点是否大于前一个节点的值即可。\n注意是「严格大于」：等于也说明不合法。\n另一种写法是递归时带上上下界 (low, high)，判断节点值是否落在区间内。', 1, 1, 1),
(323, '翻转二叉树', '给你一棵二叉树的根节点 root，翻转这棵二叉树，并返回其根节点。\n翻转指的是把每个节点的左右子树交换位置。', '一行：二叉树的层序数组（null 表示空节点）', '输出翻转后的二叉树层序数组', '[4,2,7,1,3,6,9]\n', '[4,7,2,9,6,3,1]\n', 'EASY', 11, 1000, 64, '', 'import java.util.*;\n\npublic class Main {\n    static class TreeNode {\n        int val;\n        TreeNode left, right;\n        TreeNode(int v) { val = v; }\n    }\n\n    static TreeNode build(String line) {\n        line = line.trim();\n        if (line.startsWith(\"[\")) line = line.substring(1, line.length() - 1);\n        if (line.isEmpty()) return null;\n        String[] parts = line.split(\",\");\n        TreeNode root = new TreeNode(Integer.parseInt(parts[0].trim()));\n        java.util.Queue<TreeNode> q = new java.util.LinkedList<>();\n        q.offer(root);\n        int i = 1;\n        while (!q.isEmpty() && i < parts.length) {\n            TreeNode cur = q.poll();\n            String l = parts[i++].trim();\n            if (!\"null\".equals(l)) {\n                cur.left = new TreeNode(Integer.parseInt(l));\n                q.offer(cur.left);\n            }\n            if (i < parts.length) {\n                String r = parts[i++].trim();\n                if (!\"null\".equals(r)) {\n                    cur.right = new TreeNode(Integer.parseInt(r));\n                    q.offer(cur.right);\n                }\n            }\n        }\n        return root;\n    }\n\n    static String serialize(TreeNode root) {\n        if (root == null) return \"[]\";\n        java.util.List<String> out = new java.util.ArrayList<>();\n        java.util.Queue<TreeNode> q = new java.util.LinkedList<>();\n        q.offer(root);\n        while (!q.isEmpty()) {\n            TreeNode cur = q.poll();\n            if (cur == null) { out.add(\"null\"); continue; }\n            out.add(String.valueOf(cur.val));\n            q.offer(cur.left);\n            q.offer(cur.right);\n        }\n        while (!out.isEmpty() && \"null\".equals(out.get(out.size() - 1))) out.remove(out.size() - 1);\n        return \"[\" + String.join(\",\", out) + \"]\";\n    }\n\n    static TreeNode invert(TreeNode node) {\n        if (node == null) return null;\n        TreeNode t = node.left;\n        node.left = invert(node.right);\n        node.right = invert(t);\n        return node;\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        TreeNode root = build(sc.nextLine());\n        System.out.println(serialize(invert(root)));\n    }\n}\n', '递归：交换当前节点的左右孩子，再分别递归翻转左右子树。\n也可以层序遍历，逐节点交换左右孩子。时间 O(n)。', 1, 1, 1),
(324, '二叉树的右视图', '给定一个二叉树的根节点 root，想象自己站在它的右侧，按照从顶部到底部的顺序，返回从右侧所能看到的节点值（即每一层最右边的节点）。', '一行：二叉树的层序数组（null 表示空节点）', '输出右视图节点值数组，格式为 [a,b,c]', '[1,2,3,null,5,null,4]\n', '[1,3,4]\n', 'MEDIUM', 11, 1000, 64, '', 'import java.util.*;\n\npublic class Main {\n    static class TreeNode {\n        int val;\n        TreeNode left, right;\n        TreeNode(int v) { val = v; }\n    }\n\n    static TreeNode build(String line) {\n        line = line.trim();\n        if (line.startsWith(\"[\")) line = line.substring(1, line.length() - 1);\n        if (line.isEmpty()) return null;\n        String[] parts = line.split(\",\");\n        TreeNode root = new TreeNode(Integer.parseInt(parts[0].trim()));\n        java.util.Queue<TreeNode> q = new java.util.LinkedList<>();\n        q.offer(root);\n        int i = 1;\n        while (!q.isEmpty() && i < parts.length) {\n            TreeNode cur = q.poll();\n            String l = parts[i++].trim();\n            if (!\"null\".equals(l)) {\n                cur.left = new TreeNode(Integer.parseInt(l));\n                q.offer(cur.left);\n            }\n            if (i < parts.length) {\n                String r = parts[i++].trim();\n                if (!\"null\".equals(r)) {\n                    cur.right = new TreeNode(Integer.parseInt(r));\n                    q.offer(cur.right);\n                }\n            }\n        }\n        return root;\n    }\n\n    static String serialize(TreeNode root) {\n        if (root == null) return \"[]\";\n        java.util.List<String> out = new java.util.ArrayList<>();\n        java.util.Queue<TreeNode> q = new java.util.LinkedList<>();\n        q.offer(root);\n        while (!q.isEmpty()) {\n            TreeNode cur = q.poll();\n            if (cur == null) { out.add(\"null\"); continue; }\n            out.add(String.valueOf(cur.val));\n            q.offer(cur.left);\n            q.offer(cur.right);\n        }\n        while (!out.isEmpty() && \"null\".equals(out.get(out.size() - 1))) out.remove(out.size() - 1);\n        return \"[\" + String.join(\",\", out) + \"]\";\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        TreeNode root = build(sc.nextLine());\n\n        List<String> res = new ArrayList<>();\n        if (root != null) {\n            Queue<TreeNode> q = new LinkedList<>();\n            q.offer(root);\n            while (!q.isEmpty()) {\n                int size = q.size();\n                for (int i = 0; i < size; i++) {\n                    TreeNode cur = q.poll();\n                    if (i == size - 1) res.add(String.valueOf(cur.val));   // 每层最后一个\n                    if (cur.left != null) q.offer(cur.left);\n                    if (cur.right != null) q.offer(cur.right);\n                }\n            }\n        }\n        System.out.println(\"[\" + String.join(\",\", res) + \"]\");\n    }\n}\n', '层序遍历（BFS）：每处理完一层的所有节点后，把该层最后一个节点的值加入结果。\n关键是内层 for 循环前先记录 len = queue.size()，这样能准确区分每一层。', 1, 1, 1),
(325, '多数元素', '给定一个大小为 n 的数组 nums，返回其中的多数元素。\n多数元素是指在数组中出现次数大于 n/2 的元素。\n你可以假设数组是非空的，并且给定的数组总是存在多数元素。', '第一行：数组长度 n\n第二行：n 个整数', '输出多数元素', '3\n3 2 3\n', '3\n', 'EASY', 1, 1000, 64, '', 'import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] nums = new int[n];\n        for (int i = 0; i < n; i++) nums[i] = sc.nextInt();\n\n        // 摩尔投票：不同的数两两抵消，剩下的就是出现次数超过一半的那个\n        int candidate = nums[0], count = 1;\n        for (int i = 1; i < n; i++) {\n            if (count == 0) {\n                candidate = nums[i];\n                count = 1;\n            } else if (nums[i] == candidate) {\n                count++;\n            } else {\n                count--;\n            }\n        }\n        System.out.println(candidate);\n    }\n}\n', '摩尔投票法（Boyer-Moore）：维护一个候选值和计数器。\n遇到相同的数计数 +1，遇到不同的数计数 -1；计数归零就换候选值。\n因为多数元素出现次数超过 n/2，即使和其他所有元素一一抵消，最后也一定会剩下它。\n时间 O(n)，空间 O(1)。', 1, 1, 1),
(326, '字符串相加', '给定两个字符串形式的非负整数 num1 和 num2，计算它们的和并同样以字符串形式返回。\n你不能使用任何內建的用于处理大整数的库，也不能直接将输入的字符串转换为整数形式。', '第一行：num1\n第二行：num2', '输出两数之和（字符串形式）', '11\n123\n', '134\n', 'EASY', 1, 1000, 64, '', 'import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String a = sc.nextLine().trim();\n        String b = sc.nextLine().trim();\n\n        // 从末尾逐位相加，处理进位\n        StringBuilder sb = new StringBuilder();\n        int i = a.length() - 1, j = b.length() - 1, carry = 0;\n        while (i >= 0 || j >= 0 || carry > 0) {\n            int x = i >= 0 ? a.charAt(i--) - \'0\' : 0;\n            int y = j >= 0 ? b.charAt(j--) - \'0\' : 0;\n            int sum = x + y + carry;\n            sb.append(sum % 10);\n            carry = sum / 10;\n        }\n        System.out.println(sb.reverse().toString());\n    }\n}\n', '模拟竖式加法：两个指针从字符串末尾往前移动，逐位相加并维护进位。\n循环条件要带上 carry > 0，否则最高位的进位会丢。\n结果先逆序追加、最后整体反转。', 1, 1, 1),
(327, '字符串转换整数(atoi)', '请你来实现一个 myAtoi(string s) 函数，使其能将字符串转换成一个 32 位有符号整数。\n处理规则：\n  1. 读入字符串并丢弃无用的前导空格\n  2. 检查下一个字符是 \'+\' 还是 \'-\'，决定结果的正负号；若都不是则假定为正\n  3. 读入接下来的数字，直到遇到非数字字符或到达结尾；如果没有读到数字，结果为 0\n  4. 结果小于 -2^31 就返回 -2^31，大于 2^31-1 就返回 2^31-1', '一行字符串 s', '输出转换后的整数', '42\n', '42\n', 'MEDIUM', 1, 1000, 64, '', 'import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        // 前后空格都可能存在，这里保留原样（规则里只丢弃前导空格）\n        String s = sc.hasNextLine() ? sc.nextLine() : \"\";\n\n        int i = 0, n = s.length();\n        while (i < n && s.charAt(i) == \' \') i++;\n\n        int sign = 1;\n        if (i < n && (s.charAt(i) == \'+\' || s.charAt(i) == \'-\')) {\n            sign = s.charAt(i) == \'-\' ? -1 : 1;\n            i++;\n        }\n\n        long val = 0;\n        while (i < n && Character.isDigit(s.charAt(i))) {\n            val = val * 10 + (s.charAt(i) - \'0\');\n            if (sign == 1 && val > Integer.MAX_VALUE) {\n                System.out.println(Integer.MAX_VALUE);\n                return;\n            }\n            if (sign == -1 && -val < Integer.MIN_VALUE) {\n                System.out.println(Integer.MIN_VALUE);\n                return;\n            }\n            i++;\n        }\n        System.out.println(sign * val);\n    }\n}\n', '按规则顺序处理即可，难点在边界：\n  1. 跳过前导空格 → 2. 取正负号 → 3. 连续读数字\n  4. 用 long 累积结果，在每步之后立刻判断是否越界，越界要返回 Integer.MAX_VALUE / MIN_VALUE（题目的截断规则）。', 1, 1, 1),
(328, '验证回文串', '如果在将所有大写字符转换为小写字符、并移除所有非字母数字字符之后，短语正着读和反着读都一样，则可以认为该短语是一个回文串。\n给你一个字符串 s，如果它是回文串，返回 true；否则返回 false。', '一行字符串 s', '输出 true 或 false', 'A man, a plan, a canal: Panama\n', 'true\n', 'EASY', 1, 1000, 64, '', 'import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String s = sc.nextLine();\n\n        int l = 0, r = s.length() - 1;\n        boolean ok = true;\n        while (l < r) {\n            char a = s.charAt(l), b = s.charAt(r);\n            if (!Character.isLetterOrDigit(a)) { l++; continue; }\n            if (!Character.isLetterOrDigit(b)) { r--; continue; }\n            if (Character.toLowerCase(a) != Character.toLowerCase(b)) { ok = false; break; }\n            l++;\n            r--;\n        }\n        System.out.println(ok);\n    }\n}\n', '左右双指针往中间走：遇到非字母数字字符就跳过（对应「移除」这一步），其余字符统一转小写后比较。\n这样不用真的构造新字符串，空间 O(1)。', 1, 1, 1),
(329, '旋转图像', '给定一个 n × n 的二维矩阵 matrix 表示一个图像，请你将图像顺时针旋转 90 度。\n你必须在原地旋转图像，这意味着你需要直接修改输入的二维矩阵，不要使用另一个矩阵来旋转。', '第一行：矩阵阶数 n\n接下来 n 行，每行 n 个整数', '输出旋转后的矩阵，每行 n 个整数（空格分隔）', '3\n1 2 3\n4 5 6\n7 8 9\n', '7 4 1\n8 5 2\n9 6 3\n', 'MEDIUM', 1, 1000, 64, '', 'import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[][] m = new int[n][n];\n        for (int i = 0; i < n; i++)\n            for (int j = 0; j < n; j++) m[i][j] = sc.nextInt();\n\n        // 顺时针 90 度 = 先沿主对角线转置，再把每一行左右翻转\n        for (int i = 0; i < n; i++)\n            for (int j = i + 1; j < n; j++) {\n                int t = m[i][j]; m[i][j] = m[j][i]; m[j][i] = t;\n            }\n        for (int i = 0; i < n; i++)\n            for (int l = 0, r = n - 1; l < r; l++, r--) {\n                int t = m[i][l]; m[i][l] = m[i][r]; m[i][r] = t;\n            }\n\n        StringBuilder sb = new StringBuilder();\n        for (int i = 0; i < n; i++) {\n            for (int j = 0; j < n; j++) {\n                if (j > 0) sb.append(\" \");\n                sb.append(m[i][j]);\n            }\n            sb.append(\"\\n\");\n        }\n        System.out.print(sb);\n    }\n}\n', '把「旋转」拆成两步原地操作：\n  1. 沿主对角线转置：(i,j) 与 (j,i) 交换；\n  2. 每一行左右翻转。\n两步叠加正好等价于顺时针旋转 90 度，全程不需要额外矩阵。', 1, 1, 1),
(330, '缺失的第一个正数', '给你一个未排序的整数数组 nums，请你找出其中没有出现的最小的正整数。\n请你实现时间复杂度为 O(n) 并且只使用常数级别额外空间的解决方案。', '第一行：数组长度 n\n第二行：n 个整数', '输出没有出现的最小正整数', '3\n1 2 0\n', '3\n', 'HARD', 1, 1000, 64, '', 'import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] nums = new int[n];\n        for (int i = 0; i < n; i++) nums[i] = sc.nextInt();\n\n        // 原地哈希：把数值 v（1<=v<=n）放到下标 v-1 的位置上\n        for (int i = 0; i < n; i++) {\n            while (nums[i] >= 1 && nums[i] <= n && nums[nums[i] - 1] != nums[i]) {\n                int idx = nums[i] - 1;\n                int t = nums[i]; nums[i] = nums[idx]; nums[idx] = t;\n            }\n        }\n        // 第一个「下标 i 上不是 i+1」的位置，答案就是 i+1\n        for (int i = 0; i < n; i++) {\n            if (nums[i] != i + 1) {\n                System.out.println(i + 1);\n                return;\n            }\n        }\n        System.out.println(n + 1);\n    }\n}\n', '答案一定落在 [1, n+1] 范围内。把数组本身当成哈希表用：\n把值 v（1 ≤ v ≤ n）交换到下标 v-1 的位置上（用 while 一直换到不能换为止）。\n之后再扫一遍，第一个满足 nums[i] != i+1 的位置答案就是 i+1；\n如果全对上了，答案就是 n+1。时间 O(n)，空间 O(1)。', 1, 1, 1),
(331, '乘积最大子数组', '给你一个整数数组 nums，请你找出数组中乘积最大的非空连续子数组（该子数组中至少包含一个数字），并返回该子数组所对应的乘积。', '第一行：数组长度 n\n第二行：n 个整数', '输出最大乘积', '3\n2 3 -2\n', '6\n', 'MEDIUM', 13, 1000, 64, '', 'import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] nums = new int[n];\n        for (int i = 0; i < n; i++) nums[i] = sc.nextInt();\n\n        // 同时维护「以当前元素结尾的最大乘积」和「最小乘积」——负数乘最小可能变最大\n        long max = nums[0], min = nums[0], best = nums[0];\n        for (int i = 1; i < n; i++) {\n            long v = nums[i];\n            long a = max * v, b = min * v;\n            max = Math.max(v, Math.max(a, b));\n            min = Math.min(v, Math.min(a, b));\n            best = Math.max(best, max);\n        }\n        System.out.println(best);\n    }\n}\n', '和「最大子序和」类似，但乘法有符号翻转的问题：\n一个很小的负数乘上负数会变成很大的正数，所以必须同时维护最大值和最小值两个状态。\n  新 max = max(v, max*v, min*v)\n  新 min = min(v, max*v, min*v)   ← 注意用「旧的」max/min 计算\n答案取每步 max 的最大值。', 1, 1, 1),
(332, '两两交换链表中的节点', '给你一个链表，两两交换其中相邻的节点，并返回交换后链表的头节点。\n你必须在不修改节点内部的值的情况下完成本题（即只能进行节点交换）。', '一行链表，格式如 1->2->3->4->NULL', '输出交换后的链表，格式如 2->1->4->3->NULL', '1->2->3->4->NULL\n', '2->1->4->3->NULL\n', 'MEDIUM', 2, 1000, 64, '', 'import java.util.*;\n\npublic class Main {\n    static class ListNode {\n        int val;\n        ListNode next;\n        ListNode(int v) { val = v; }\n    }\n\n    static ListNode build(String line) {\n        line = line.trim();\n        if (line.endsWith(\"->NULL\")) line = line.substring(0, line.length() - 6);\n        if (line.isEmpty() || \"NULL\".equals(line)) return null;\n        String[] parts = line.split(\"->\");\n        ListNode dummy = new ListNode(0), cur = dummy;\n        for (String s : parts) {\n            cur.next = new ListNode(Integer.parseInt(s.trim()));\n            cur = cur.next;\n        }\n        return dummy.next;\n    }\n\n    static String serialize(ListNode head) {\n        StringBuilder sb = new StringBuilder();\n        while (head != null) {\n            sb.append(head.val).append(\"->\");\n            head = head.next;\n        }\n        sb.append(\"NULL\");\n        return sb.toString();\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        ListNode head = build(sc.nextLine());\n\n        ListNode dummy = new ListNode(0);\n        dummy.next = head;\n        ListNode prev = dummy;\n        while (prev.next != null && prev.next.next != null) {\n            ListNode first = prev.next;\n            ListNode second = first.next;\n            // prev -> second -> first -> 后面的部分\n            first.next = second.next;\n            second.next = first;\n            prev.next = second;\n            prev = first;          // 下一轮从 first 后面开始\n        }\n        System.out.println(serialize(dummy.next));\n    }\n}\n', '加一个哑节点 dummy 指向 head，用 prev 指向「待交换两节点的前一个」。\n每轮交换 prev 后面的两个节点（三根指针的顺序不能错）：\n  first.next = second.next;  second.next = first;  prev.next = second;\n然后把 prev 推进到 first（它现在位于两个节点之后），继续下一轮。', 1, 1, 1),
(333, '删除排序链表中的重复元素', '给定一个已排序的链表的头 head，删除所有重复的元素，使每个元素只出现一次。\n返回已排序的链表。', '一行链表，格式如 1->1->2->3->3->NULL', '输出去重后的链表，格式如 1->2->3->NULL', '1->1->2->3->3->NULL\n', '1->2->3->NULL\n', 'EASY', 2, 1000, 64, '', 'import java.util.*;\n\npublic class Main {\n    static class ListNode {\n        int val;\n        ListNode next;\n        ListNode(int v) { val = v; }\n    }\n\n    static ListNode build(String line) {\n        line = line.trim();\n        if (line.endsWith(\"->NULL\")) line = line.substring(0, line.length() - 6);\n        if (line.isEmpty() || \"NULL\".equals(line)) return null;\n        String[] parts = line.split(\"->\");\n        ListNode dummy = new ListNode(0), cur = dummy;\n        for (String s : parts) {\n            cur.next = new ListNode(Integer.parseInt(s.trim()));\n            cur = cur.next;\n        }\n        return dummy.next;\n    }\n\n    static String serialize(ListNode head) {\n        StringBuilder sb = new StringBuilder();\n        while (head != null) {\n            sb.append(head.val).append(\"->\");\n            head = head.next;\n        }\n        sb.append(\"NULL\");\n        return sb.toString();\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        ListNode head = build(sc.nextLine());\n\n        ListNode cur = head;\n        while (cur != null && cur.next != null) {\n            if (cur.val == cur.next.val) {\n                cur.next = cur.next.next;      // 跳过重复节点\n            } else {\n                cur = cur.next;\n            }\n        }\n        System.out.println(serialize(head));\n    }\n}\n', '链表已经有序，所以重复元素必然相邻。\n用 cur 遍历：若 cur.val == cur.next.val 就把 cur.next 指到再下一个（跳过）；\n否则 cur 前进一格。注意内层不移动 cur，因为可能有连续多个重复值。', 1, 1, 1),
(334, '环形链表II', '给定一个链表的头节点 head，返回链表开始入环的第一个节点。如果链表无环，则返回 -1。\n链表的节点值依次给出，用 pos 表示尾节点连到的节点下标（从 0 开始）；pos = -1 表示无环。\n要求不使用额外空间。', '第一行：节点个数 n\n第二行：n 个节点值（空格分隔）\n第三行：pos', '输出入环点的节点下标；无环输出 -1', '4\n3 2 0 -4\n1\n', '1\n', 'MEDIUM', 2, 1000, 64, '', 'import java.util.*;\n\npublic class Main {\n    static class ListNode {\n        int val;\n        ListNode next;\n        ListNode(int v) { val = v; }\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] vals = new int[n];\n        for (int i = 0; i < n; i++) vals[i] = sc.nextInt();\n        int pos = sc.nextInt();\n\n        ListNode[] nodes = new ListNode[n];\n        for (int i = 0; i < n; i++) nodes[i] = new ListNode(vals[i]);\n        for (int i = 0; i < n - 1; i++) nodes[i].next = nodes[i + 1];\n        if (pos >= 0 && pos < n) nodes[n - 1].next = nodes[pos];\n\n        // 快慢指针先找到相遇点\n        ListNode slow = n > 0 ? nodes[0] : null, fast = slow;\n        while (fast != null && fast.next != null) {\n            slow = slow.next;\n            fast = fast.next.next;\n            if (slow == fast) break;\n        }\n        if (fast == null || fast.next == null) {\n            System.out.println(-1);\n            return;\n        }\n        // 头节点和相遇点同时走，相遇处就是入环点\n        ListNode p = n > 0 ? nodes[0] : null;\n        while (p != slow) {\n            p = p.next;\n            slow = slow.next;\n        }\n        for (int i = 0; i < n; i++) {\n            if (nodes[i] == p) {\n                System.out.println(i);\n                return;\n            }\n        }\n        System.out.println(-1);\n    }\n}\n', '两段式快慢指针：\n  1. 先用快慢指针判断有没有环，相遇点在环内；\n  2. 让一个指针回到头节点，然后两个指针都每次走一步，它们再次相遇的位置就是入环点。\n原理：设头到入环点为 a，入环点到相遇点为 b，相遇点回到入环点为 c，则 fast 走了 a+b+c+b，slow 走了 a+b，而 fast = 2×slow，可推出 a = c。', 1, 1, 1),
(335, '删除链表的倒数第N个节点', '给你一个链表，删除链表的倒数第 n 个节点，并且返回链表的头节点。\n要求只遍历一次链表。', '第一行：节点个数 len\n第二行：len 个节点值（空格分隔）\n第三行：n', '输出删除后的链表，格式如 1->2->3->NULL', '5\n1 2 3 4 5\n2\n', '1->2->3->5->NULL\n', 'MEDIUM', 2, 1000, 64, '', 'import java.util.*;\n\npublic class Main {\n    static class ListNode {\n        int val;\n        ListNode next;\n        ListNode(int v) { val = v; }\n    }\n\n    static ListNode build(String line) {\n        line = line.trim();\n        if (line.endsWith(\"->NULL\")) line = line.substring(0, line.length() - 6);\n        if (line.isEmpty() || \"NULL\".equals(line)) return null;\n        String[] parts = line.split(\"->\");\n        ListNode dummy = new ListNode(0), cur = dummy;\n        for (String s : parts) {\n            cur.next = new ListNode(Integer.parseInt(s.trim()));\n            cur = cur.next;\n        }\n        return dummy.next;\n    }\n\n    static String serialize(ListNode head) {\n        StringBuilder sb = new StringBuilder();\n        while (head != null) {\n            sb.append(head.val).append(\"->\");\n            head = head.next;\n        }\n        sb.append(\"NULL\");\n        return sb.toString();\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int len = sc.nextInt();\n        ListNode dummy = new ListNode(0), cur = dummy;\n        for (int i = 0; i < len; i++) {\n            cur.next = new ListNode(sc.nextInt());\n            cur = cur.next;\n        }\n        int n = sc.nextInt();\n\n        // 快指针先走 n 步，然后快慢一起走，慢指针最终停在待删节点的前一个\n        ListNode fast = dummy, slow = dummy;\n        for (int i = 0; i < n; i++) fast = fast.next;\n        while (fast.next != null) {\n            fast = fast.next;\n            slow = slow.next;\n        }\n        slow.next = slow.next.next;\n\n        System.out.println(serialize(dummy.next));\n    }\n}\n', '一次遍历的双指针法：\n  1. 用哑节点 dummy 指向 head（方便处理「删头节点」的情况）；\n  2. fast 先走 n 步；\n  3. fast 和 slow 同步前进，直到 fast 走到最后一个节点。\n此时 slow 正好停在倒数第 n+1 个节点上，执行 slow.next = slow.next.next 即完成删除。', 1, 1, 1),
(336, '重排链表', '给定一个单链表 L 的头节点 head，其节点值依次为 a1, a2, …, an。\n请将其重新排列后变为：a1, an, a2, an-1, a3, an-2, …\n你不能只是单纯地改变节点内部的值，而是需要实际的进行节点交换。', '一行链表，格式如 1->2->3->4->NULL', '输出重排后的链表，格式如 1->4->2->3->NULL', '1->2->3->4->NULL\n', '1->4->2->3->NULL\n', 'MEDIUM', 2, 1000, 64, '', 'import java.util.*;\n\npublic class Main {\n    static class ListNode {\n        int val;\n        ListNode next;\n        ListNode(int v) { val = v; }\n    }\n\n    static ListNode build(String line) {\n        line = line.trim();\n        if (line.endsWith(\"->NULL\")) line = line.substring(0, line.length() - 6);\n        if (line.isEmpty() || \"NULL\".equals(line)) return null;\n        String[] parts = line.split(\"->\");\n        ListNode dummy = new ListNode(0), cur = dummy;\n        for (String s : parts) {\n            cur.next = new ListNode(Integer.parseInt(s.trim()));\n            cur = cur.next;\n        }\n        return dummy.next;\n    }\n\n    static String serialize(ListNode head) {\n        StringBuilder sb = new StringBuilder();\n        while (head != null) {\n            sb.append(head.val).append(\"->\");\n            head = head.next;\n        }\n        sb.append(\"NULL\");\n        return sb.toString();\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        ListNode head = build(sc.nextLine());\n\n        // 1. 快慢指针找中点，切成前后两半\n        ListNode slow = head, fast = head;\n        while (fast.next != null && fast.next.next != null) {\n            slow = slow.next;\n            fast = fast.next.next;\n        }\n        ListNode second = slow.next;\n        slow.next = null;\n\n        // 2. 后半段反转\n        ListNode prev = null;\n        while (second != null) {\n            ListNode next = second.next;\n            second.next = prev;\n            prev = second;\n            second = next;\n        }\n\n        // 3. 前后两半交替拼接\n        ListNode a = head, b = prev;\n        while (a != null && b != null) {\n            ListNode an = a.next, bn = b.next;\n            a.next = b;\n            b.next = an;\n            a = an;\n            b = bn;\n        }\n        System.out.println(serialize(head));\n    }\n}\n', '三步：\n  1. 快慢指针找中点，把链表切成前半段和后半段；\n  2. 反转后半段；\n  3. 两段交替拼接（每次记住各自的下一个节点再插入）。\n时间 O(n)，空间 O(1)。', 1, 1, 1),
(337, '旋转链表', '给你一个链表的头节点 head，旋转链表，将链表每个节点向右移动 k 个位置。', '第一行：链表，格式如 1->2->3->4->5->NULL\n第二行：k', '输出旋转后的链表', '1->2->3->4->5->NULL\n2\n', '4->5->1->2->3->NULL\n', 'MEDIUM', 2, 1000, 64, '', 'import java.util.*;\n\npublic class Main {\n    static class ListNode {\n        int val;\n        ListNode next;\n        ListNode(int v) { val = v; }\n    }\n\n    static ListNode build(String line) {\n        line = line.trim();\n        if (line.endsWith(\"->NULL\")) line = line.substring(0, line.length() - 6);\n        if (line.isEmpty() || \"NULL\".equals(line)) return null;\n        String[] parts = line.split(\"->\");\n        ListNode dummy = new ListNode(0), cur = dummy;\n        for (String s : parts) {\n            cur.next = new ListNode(Integer.parseInt(s.trim()));\n            cur = cur.next;\n        }\n        return dummy.next;\n    }\n\n    static String serialize(ListNode head) {\n        StringBuilder sb = new StringBuilder();\n        while (head != null) {\n            sb.append(head.val).append(\"->\");\n            head = head.next;\n        }\n        sb.append(\"NULL\");\n        return sb.toString();\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        ListNode head = build(sc.nextLine());\n        int k = Integer.parseInt(sc.nextLine().trim());\n\n        if (head == null || head.next == null) {\n            System.out.println(serialize(head));\n            return;\n        }\n        // 先求长度并找到尾节点\n        int len = 1;\n        ListNode tail = head;\n        while (tail.next != null) {\n            tail = tail.next;\n            len++;\n        }\n        k = k % len;\n        if (k != 0) {\n            // 首尾相接成环，再在「倒数第 k 个」处断开\n            tail.next = head;\n            ListNode newTail = head;\n            for (int i = 0; i < len - k - 1; i++) newTail = newTail.next;\n            head = newTail.next;\n            newTail.next = null;\n        }\n        System.out.println(serialize(head));\n    }\n}\n', '先遍历一遍求出长度 len 和尾节点，然后 k %= len（k 可能大于长度）。\n把尾节点接到头节点上形成环，再走 len - k 步找到新的尾节点，断开即可。\n时间 O(n)，空间 O(1)。', 1, 1, 1),
(338, '合并K个升序链表', '给你一个链表数组，每个链表都已经按升序排列。\n请你将所有链表合并到一个升序链表中，返回合并后的链表。', '第一行：链表个数 k\n接下来 k 行，每行一个升序链表，格式如 1->4->5->NULL', '输出合并后的链表', '3\n1->4->5->NULL\n1->3->4->NULL\n2->6->NULL\n', '1->1->2->3->4->4->5->6->NULL\n', 'HARD', 2, 1000, 64, '', 'import java.util.*;\n\npublic class Main {\n    static class ListNode {\n        int val;\n        ListNode next;\n        ListNode(int v) { val = v; }\n    }\n\n    static ListNode build(String line) {\n        line = line.trim();\n        if (line.endsWith(\"->NULL\")) line = line.substring(0, line.length() - 6);\n        if (line.isEmpty() || \"NULL\".equals(line)) return null;\n        String[] parts = line.split(\"->\");\n        ListNode dummy = new ListNode(0), cur = dummy;\n        for (String s : parts) {\n            cur.next = new ListNode(Integer.parseInt(s.trim()));\n            cur = cur.next;\n        }\n        return dummy.next;\n    }\n\n    static String serialize(ListNode head) {\n        StringBuilder sb = new StringBuilder();\n        while (head != null) {\n            sb.append(head.val).append(\"->\");\n            head = head.next;\n        }\n        sb.append(\"NULL\");\n        return sb.toString();\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int k = Integer.parseInt(sc.nextLine().trim());\n        ListNode[] lists = new ListNode[k];\n        for (int i = 0; i < k; i++) lists[i] = build(sc.nextLine());\n\n        // 小顶堆里只放每个链表当前的头节点\n        PriorityQueue<ListNode> heap = new PriorityQueue<>((a, b) -> a.val - b.val);\n        for (ListNode node : lists) {\n            if (node != null) heap.offer(node);\n        }\n\n        ListNode dummy = new ListNode(0), cur = dummy;\n        while (!heap.isEmpty()) {\n            ListNode min = heap.poll();\n            cur.next = min;\n            cur = cur.next;\n            if (min.next != null) heap.offer(min.next);\n        }\n        System.out.println(serialize(dummy.next));\n    }\n}\n', '用小顶堆做 k 路归并：堆里始终放着每条链表当前未处理的头节点。\n每次弹出最小值接到结果链表尾部，再把该节点的下一个节点压入堆。\n每个节点进出堆各一次，时间 O(N log k)（N 为节点总数），空间 O(k)。', 1, 1, 1),
(339, '排序链表', '给你链表的头结点 head，请将其按升序排列并返回排序后的链表。\n要求时间复杂度 O(n log n)、空间复杂度 O(1)。', '第一行：节点个数 n\n第二行：n 个节点值（空格分隔）', '输出排序后的链表，格式如 1->2->3->4->NULL', '4\n-1 5 3 4\n', '-1->3->4->5->NULL\n', 'MEDIUM', 2, 1000, 64, '', 'import java.util.*;\n\npublic class Main {\n    static class ListNode {\n        int val;\n        ListNode next;\n        ListNode(int v) { val = v; }\n    }\n\n    static ListNode build(String line) {\n        line = line.trim();\n        if (line.endsWith(\"->NULL\")) line = line.substring(0, line.length() - 6);\n        if (line.isEmpty() || \"NULL\".equals(line)) return null;\n        String[] parts = line.split(\"->\");\n        ListNode dummy = new ListNode(0), cur = dummy;\n        for (String s : parts) {\n            cur.next = new ListNode(Integer.parseInt(s.trim()));\n            cur = cur.next;\n        }\n        return dummy.next;\n    }\n\n    static String serialize(ListNode head) {\n        StringBuilder sb = new StringBuilder();\n        while (head != null) {\n            sb.append(head.val).append(\"->\");\n            head = head.next;\n        }\n        sb.append(\"NULL\");\n        return sb.toString();\n    }\n\n    // 归并排序：自底向上按步长两两合并，避免递归栈\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        ListNode dummy = new ListNode(0), cur = dummy;\n        for (int i = 0; i < n; i++) {\n            cur.next = new ListNode(sc.nextInt());\n            cur = cur.next;\n        }\n        ListNode head = dummy.next;\n\n        int len = 0;\n        for (ListNode p = head; p != null; p = p.next) len++;\n\n        ListNode res = new ListNode(0);\n        res.next = head;\n        for (int step = 1; step < len; step *= 2) {\n            ListNode prev = res, p = res.next;\n            while (p != null) {\n                ListNode left = p;\n                ListNode right = split(left, step);\n                p = split(right, step);\n                prev = merge(left, right, prev);\n            }\n        }\n        System.out.println(serialize(res.next));\n    }\n\n    /** 从 node 开始截取 step 个节点，返回剩余部分的头 */\n    static ListNode split(ListNode node, int step) {\n        if (node == null) return null;\n        for (int i = 1; i < step && node.next != null; i++) node = node.next;\n        ListNode rest = node.next;\n        node.next = null;\n        return rest;\n    }\n\n    static ListNode merge(ListNode a, ListNode b, ListNode prev) {\n        ListNode tail = prev;\n        while (a != null && b != null) {\n            if (a.val <= b.val) { tail.next = a; a = a.next; }\n            else { tail.next = b; b = b.next; }\n            tail = tail.next;\n        }\n        tail.next = a != null ? a : b;\n        while (tail.next != null) tail = tail.next;\n        return tail;\n    }\n}\n', '链表归并排序。自底向上版（迭代）能同时满足 O(n log n) 时间和 O(1) 空间：\n  外层 step = 1, 2, 4, … 表示每轮合并的段长；\n  内层扫描链表，每次切出长度 ≤ step 的两段，归并后接在结果链上。\nsplit 负责切断段并返回剩余部分的头节点。', 1, 1, 1),
(340, '二叉树中的最大路径和', '二叉树中的路径被定义为一条节点序列，序列中每对相邻节点之间都存在一条边。\n同一个节点在一条路径序列中至多出现一次。该路径至少包含一个节点，且不一定经过根节点。\n路径和是路径中各节点值的总和。给你二叉树的根节点 root，返回其最大路径和。', '一行：二叉树的层序数组（null 表示空节点）', '输出最大路径和', '[-10,9,20,null,null,15,7]\n', '42\n', 'HARD', 11, 1000, 64, '', 'import java.util.*;\n\npublic class Main {\n    static class TreeNode {\n        int val;\n        TreeNode left, right;\n        TreeNode(int v) { val = v; }\n    }\n\n    static TreeNode build(String line) {\n        line = line.trim();\n        if (line.startsWith(\"[\")) line = line.substring(1, line.length() - 1);\n        if (line.isEmpty()) return null;\n        String[] parts = line.split(\",\");\n        TreeNode root = new TreeNode(Integer.parseInt(parts[0].trim()));\n        java.util.Queue<TreeNode> q = new java.util.LinkedList<>();\n        q.offer(root);\n        int i = 1;\n        while (!q.isEmpty() && i < parts.length) {\n            TreeNode cur = q.poll();\n            String l = parts[i++].trim();\n            if (!\"null\".equals(l)) {\n                cur.left = new TreeNode(Integer.parseInt(l));\n                q.offer(cur.left);\n            }\n            if (i < parts.length) {\n                String r = parts[i++].trim();\n                if (!\"null\".equals(r)) {\n                    cur.right = new TreeNode(Integer.parseInt(r));\n                    q.offer(cur.right);\n                }\n            }\n        }\n        return root;\n    }\n\n    static int best = Integer.MIN_VALUE;\n\n    /** 返回「以 node 为起点向下延伸」的最大路径和 */\n    static int gain(TreeNode node) {\n        if (node == null) return 0;\n        int left = Math.max(0, gain(node.left));    // 负贡献不如不要\n        int right = Math.max(0, gain(node.right));\n        // 经过 node 并连接左右两边的路径\n        best = Math.max(best, node.val + left + right);\n        // 向上返回时只能选一边\n        return node.val + Math.max(left, right);\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        TreeNode root = build(sc.nextLine());\n        gain(root);\n        System.out.println(best);\n    }\n}\n', '后序遍历递归。对每个节点，计算「以它为起点向下走」能获得的最大收益 gain：\n  gain = node.val + max(0, gain(left), gain(right))   —— 子树收益为负时不如不走\n同时在每个节点处更新全局答案：node.val + max(0,gain(left)) + max(0,gain(right))，这对应「路径在这个节点拐弯、同时连接左右两侧」的情况。\n注意返回值只能选一边，因为向上延伸的路径不能分叉。', 1, 1, 1),
(341, '二叉树的锯齿形层次遍历', '给你二叉树的根节点 root，返回其节点值的锯齿形层序遍历。\n（即先从左往右，再从右往左进行下一层遍历，以此类推，层与层之间交替进行）。', '一行：二叉树的层序数组（null 表示空节点）', '输出锯齿形层序遍历结果，格式如 [[3],[20,9],[15,7]]', '[3,9,20,null,null,15,7]\n', '[[3],[20,9],[15,7]]\n', 'MEDIUM', 11, 1000, 64, '', 'import java.util.*;\n\npublic class Main {\n    static class TreeNode {\n        int val;\n        TreeNode left, right;\n        TreeNode(int v) { val = v; }\n    }\n\n    static TreeNode build(String line) {\n        line = line.trim();\n        if (line.startsWith(\"[\")) line = line.substring(1, line.length() - 1);\n        if (line.isEmpty()) return null;\n        String[] parts = line.split(\",\");\n        TreeNode root = new TreeNode(Integer.parseInt(parts[0].trim()));\n        java.util.Queue<TreeNode> q = new java.util.LinkedList<>();\n        q.offer(root);\n        int i = 1;\n        while (!q.isEmpty() && i < parts.length) {\n            TreeNode cur = q.poll();\n            String l = parts[i++].trim();\n            if (!\"null\".equals(l)) {\n                cur.left = new TreeNode(Integer.parseInt(l));\n                q.offer(cur.left);\n            }\n            if (i < parts.length) {\n                String r = parts[i++].trim();\n                if (!\"null\".equals(r)) {\n                    cur.right = new TreeNode(Integer.parseInt(r));\n                    q.offer(cur.right);\n                }\n            }\n        }\n        return root;\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        TreeNode root = build(sc.nextLine());\n\n        List<List<Integer>> res = new ArrayList<>();\n        if (root != null) {\n            Queue<TreeNode> q = new LinkedList<>();\n            q.offer(root);\n            boolean leftToRight = true;\n            while (!q.isEmpty()) {\n                int size = q.size();\n                List<Integer> level = new ArrayList<>();\n                for (int i = 0; i < size; i++) {\n                    TreeNode cur = q.poll();\n                    level.add(cur.val);\n                    if (cur.left != null) q.offer(cur.left);\n                    if (cur.right != null) q.offer(cur.right);\n                }\n                if (!leftToRight) Collections.reverse(level);\n                res.add(level);\n                leftToRight = !leftToRight;\n            }\n        }\n\n        StringBuilder sb = new StringBuilder(\"[\");\n        for (int i = 0; i < res.size(); i++) {\n            if (i > 0) sb.append(\",\");\n            sb.append(\"[\");\n            List<Integer> level = res.get(i);\n            for (int j = 0; j < level.size(); j++) {\n                if (j > 0) sb.append(\",\");\n                sb.append(level.get(j));\n            }\n            sb.append(\"]\");\n        }\n        sb.append(\"]\");\n        System.out.println(sb);\n    }\n}\n', '本质是层序遍历，只是奇数层（从 0 开始计数）处理完后把该层结果反转。\n另外也可以用双端队列：偶数层从尾部加、奇数层从头部加，省掉一次反转。', 1, 1, 1),
(342, '二叉搜索树中第K小的元素', '给定一个二叉搜索树的根节点 root，和一个整数 k，请你设计一个算法查找其中第 k 个最小元素（从 1 开始计数）。', '第一行：二叉搜索树的层序数组\n第二行：k', '输出第 k 小的元素值', '[3,1,4,null,2]\n1\n', '1\n', 'MEDIUM', 11, 1000, 64, '', 'import java.util.*;\n\npublic class Main {\n    static class TreeNode {\n        int val;\n        TreeNode left, right;\n        TreeNode(int v) { val = v; }\n    }\n\n    static TreeNode build(String line) {\n        line = line.trim();\n        if (line.startsWith(\"[\")) line = line.substring(1, line.length() - 1);\n        if (line.isEmpty()) return null;\n        String[] parts = line.split(\",\");\n        TreeNode root = new TreeNode(Integer.parseInt(parts[0].trim()));\n        java.util.Queue<TreeNode> q = new java.util.LinkedList<>();\n        q.offer(root);\n        int i = 1;\n        while (!q.isEmpty() && i < parts.length) {\n            TreeNode cur = q.poll();\n            String l = parts[i++].trim();\n            if (!\"null\".equals(l)) {\n                cur.left = new TreeNode(Integer.parseInt(l));\n                q.offer(cur.left);\n            }\n            if (i < parts.length) {\n                String r = parts[i++].trim();\n                if (!\"null\".equals(r)) {\n                    cur.right = new TreeNode(Integer.parseInt(r));\n                    q.offer(cur.right);\n                }\n            }\n        }\n        return root;\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        TreeNode root = build(sc.nextLine());\n        int k = Integer.parseInt(sc.nextLine().trim());\n\n        // 中序遍历 BST 得到的是升序序列，走到第 k 个即可\n        Deque<TreeNode> stack = new ArrayDeque<>();\n        TreeNode cur = root;\n        int count = 0;\n        while (cur != null || !stack.isEmpty()) {\n            while (cur != null) {\n                stack.push(cur);\n                cur = cur.left;\n            }\n            cur = stack.pop();\n            if (++count == k) {\n                System.out.println(cur.val);\n                return;\n            }\n            cur = cur.right;\n        }\n    }\n}\n', 'BST 的中序遍历是升序的，所以只要中序遍历到第 k 个节点即可。\n用栈模拟中序遍历（迭代版），数到 k 就输出。\n相比「先全部遍历存成列表」，这样可以提前返回，不用走完整棵树。', 1, 1, 1),
(343, '滑动窗口最大值', '给你一个整数数组 nums，有一个大小为 k 的滑动窗口从数组的最左侧移动到数组的最右侧。\n你只可以看到在滑动窗口内的 k 个数字，滑动窗口每次只向右移动一位。\n返回滑动窗口中的最大值。', '第一行：数组长度 n 和窗口大小 k（空格分隔）\n第二行：n 个整数', '输出每个窗口的最大值，格式为 [a,b,c]', '8 3\n1 3 -1 -3 5 3 6 7\n', '[3,3,5,5,6,7]\n', 'HARD', 2, 1000, 64, '', 'import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int k = sc.nextInt();\n        int[] nums = new int[n];\n        for (int i = 0; i < n; i++) nums[i] = sc.nextInt();\n\n        // 单调队列：存下标，对应的值从队头到队尾递减\n        Deque<Integer> dq = new ArrayDeque<>();\n        List<String> res = new ArrayList<>();\n        for (int i = 0; i < n; i++) {\n            // 队头超出窗口范围就弹出\n            if (!dq.isEmpty() && dq.peekFirst() <= i - k) dq.pollFirst();\n            // 队尾比当前值小的都弹掉（它们不可能再成为最大值）\n            while (!dq.isEmpty() && nums[dq.peekLast()] <= nums[i]) dq.pollLast();\n            dq.offerLast(i);\n            if (i >= k - 1) res.add(String.valueOf(nums[dq.peekFirst()]));\n        }\n        System.out.println(\"[\" + String.join(\",\", res) + \"]\");\n    }\n}\n', '单调队列（双端队列）存下标，队列里对应的值保持递减：\n  1. 队头下标如果已经滑出窗口，弹出；\n  2. 从队尾开始，把所有比当前值小的下标都弹掉（它们永远不会再成为最大值）；\n  3. 当前下标入队；队头就是当前窗口最大值。\n每个元素最多进出队一次，时间 O(n)。', 1, 1, 1),
(344, '课程表II', '现在你总共有 numCourses 门课需要选，记为 0 到 numCourses-1。\n给你一个数组 prerequisites，其中 prerequisites[i] = [ai, bi]，表示在选修课程 ai 前必须先选修 bi。\n请返回你为了学完所有课程所安排的学习顺序。\n如果有多个正确顺序，请返回字典序最小的那个。如果不可能完成所有课程，返回空数组 []。', '第一行：课程数 numCourses\n第二行：先修关系条数 m\n接下来 m 行，每行两个整数 ai bi', '输出学习顺序（空格分隔）；无法完成则输出 []', '4\n3\n1 0\n2 0\n3 1\n', '0 1 2 3\n', 'MEDIUM', 12, 1000, 64, '', 'import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int m = sc.nextInt();\n\n        List<List<Integer>> graph = new ArrayList<>();\n        for (int i = 0; i < n; i++) graph.add(new ArrayList<>());\n        int[] indegree = new int[n];\n        for (int i = 0; i < m; i++) {\n            int a = sc.nextInt(), b = sc.nextInt();   // 先修 b 才能修 a\n            graph.get(b).add(a);\n            indegree[a]++;\n        }\n\n        // 小顶堆保证每次取编号最小的可修课程 → 字典序最小\n        PriorityQueue<Integer> pq = new PriorityQueue<>();\n        for (int i = 0; i < n; i++) {\n            if (indegree[i] == 0) pq.offer(i);\n        }\n\n        List<String> order = new ArrayList<>();\n        while (!pq.isEmpty()) {\n            int cur = pq.poll();\n            order.add(String.valueOf(cur));\n            for (int next : graph.get(cur)) {\n                if (--indegree[next] == 0) pq.offer(next);\n            }\n        }\n\n        if (order.size() != n) {\n            System.out.println(\"[]\");\n        } else {\n            System.out.println(String.join(\" \", order));\n        }\n    }\n}\n', '拓扑排序（BFS 版）：\n  1. 建图并统计每个节点的入度；\n  2. 把所有入度为 0 的节点放入队列；\n  3. 每次取一个节点输出，并把它的邻居入度减 1，减到 0 就入队。\n若最终输出的节点数少于总数，说明图里有环，无法完成。\n为了得到字典序最小的答案，把普通队列换成小顶堆（优先队列）。', 1, 1, 1),
(345, '最长有效括号', '给你一个只包含 \'(\' 和 \')\' 的字符串，找出最长有效（格式正确且连续）括号子串的长度。', '一行字符串 s（只含圆括号）', '输出最长有效括号子串的长度', '(()\n', '2\n', 'HARD', 1, 1000, 64, '', 'import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String s = sc.nextLine().trim();\n\n        // 栈里存「还没被匹配的下标」，栈底放一个哨兵 -1\n        Deque<Integer> stack = new ArrayDeque<>();\n        stack.push(-1);\n        int best = 0;\n        for (int i = 0; i < s.length(); i++) {\n            if (s.charAt(i) == \'(\') {\n                stack.push(i);\n            } else {\n                stack.pop();\n                if (stack.isEmpty()) {\n                    stack.push(i);          // 这个右括号没人匹配，成为新的分隔点\n                } else {\n                    best = Math.max(best, i - stack.peek());\n                }\n            }\n        }\n        System.out.println(best);\n    }\n}\n', '用栈存下标，而不是存字符：\n  栈底先放 -1 作为「上一个无法匹配的位置」；\n  遇到 \'(\' 就压入它的下标；\n  遇到 \')\' 就弹栈 —— 如果栈空了，说明这个右括号多余，把它的下标压入作为新基准；\n  否则当前有效长度 = 当前下标 - 栈顶下标，更新答案。\n时间 O(n)，空间 O(n)。', 1, 1, 1),
(346, 'N皇后', '按照国际象棋的规则，皇后可以攻击与之处在同一行或同一列或同一斜线上的棋子。\nn 皇后问题研究的是如何将 n 个皇后放置在 n×n 的棋盘上，并且使皇后彼此之间不能相互攻击。\n给你一个整数 n，返回所有不同的解决方案的数量。', '一行：整数 n', '输出合法方案的数量', '4\n', '2\n', 'HARD', 15, 1000, 64, '', 'import java.util.*;\n\npublic class Main {\n    static int count = 0;\n    static int n;\n    // 分别记录列、主对角线（row-col）、副对角线（row+col）是否已被占用\n    static boolean[] col, diag1, diag2;\n\n    static void dfs(int row) {\n        if (row == n) { count++; return; }\n        for (int c = 0; c < n; c++) {\n            int d1 = row - c + n;      // 加 n 偏移，避免负数下标\n            int d2 = row + c;\n            if (col[c] || diag1[d1] || diag2[d2]) continue;\n            col[c] = diag1[d1] = diag2[d2] = true;\n            dfs(row + 1);\n            col[c] = diag1[d1] = diag2[d2] = false;\n        }\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        n = sc.nextInt();\n        col = new boolean[n];\n        diag1 = new boolean[2 * n + 1];\n        diag2 = new boolean[2 * n + 1];\n        dfs(0);\n        System.out.println(count);\n    }\n}\n', '逐行回溯：每行放一个皇后，用三个布尔数组分别记录「列」「主对角线」「副对角线」是否被占用。\n  主对角线特征值：row - col（加偏移避免负数）；副对角线特征值：row + col。\n放完一行就递归下一行，冲突则剪枝。放满 n 行就得到一个合法方案。', 1, 1, 1),
(347, '最大正方形', '在一个由 \'0\' 和 \'1\' 组成的二维矩阵内，找到只包含 \'1\' 的最大正方形，并返回其面积。', '第一行：行数 m 和列数 n（空格分隔）\n接下来 m 行，每行一个长度为 n 的 01 字符串', '输出最大正方形的面积', '4 5\n10100\n10111\n11111\n10010\n', '4\n', 'MEDIUM', 13, 1000, 64, '', 'import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int m = sc.nextInt(), n = sc.nextInt();\n        int[][] dp = new int[m + 1][n + 1];\n        int maxSide = 0;\n        for (int i = 1; i <= m; i++) {\n            String row = sc.next();\n            for (int j = 1; j <= n; j++) {\n                if (row.charAt(j - 1) == \'1\') {\n                    // 以 (i,j) 为右下角的最大正方形边长\n                    dp[i][j] = 1 + Math.min(dp[i - 1][j - 1], Math.min(dp[i - 1][j], dp[i][j - 1]));\n                    maxSide = Math.max(maxSide, dp[i][j]);\n                }\n            }\n        }\n        System.out.println(maxSide * maxSide);\n    }\n}\n', '二维 DP：dp[i][j] 表示「以 (i,j) 为右下角的最大正方形边长」。\n  当 matrix[i][j] == \'1\' 时：dp[i][j] = 1 + min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1])\n直觉是：右下角能扩大成多大，取决于上、左、左上三个位置的最小值。\n答案就是最大边长的平方。时间 O(mn)。', 1, 1, 1),
(348, '接雨水', '给定 n 个非负整数表示每个宽度为 1 的柱子的高度图，计算按此排列的柱子，下雨之后能接多少雨水。', '第一行：柱子个数 n\n第二行：n 个非负整数', '输出能接的雨水总量', '12\n0 1 0 2 1 0 1 3 2 1 2 1\n', '6\n', 'HARD', 1, 1000, 64, '', 'import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] h = new int[n];\n        for (int i = 0; i < n; i++) h[i] = sc.nextInt();\n\n        // 双指针：每个位置能接的水 = min(左边最高, 右边最高) - 自身高度\n        int l = 0, r = n - 1, leftMax = 0, rightMax = 0, water = 0;\n        while (l < r) {\n            leftMax = Math.max(leftMax, h[l]);\n            rightMax = Math.max(rightMax, h[r]);\n            // 谁那一侧的天花板低，就结算谁——因为它的上限已经确定了\n            if (leftMax < rightMax) {\n                water += leftMax - h[l];\n                l++;\n            } else {\n                water += rightMax - h[r];\n                r--;\n            }\n        }\n        System.out.println(water);\n    }\n}\n', '双指针解法：每个位置能接的水 = min(左侧最大高度, 右侧最大高度) - 该位置高度。\n用左右两个指针从两端向中间靠拢，同时维护 leftMax 和 rightMax：\n  若 leftMax < rightMax，则左指针位置的「右侧最大高度」一定不低于 rightMax，它的接水量已经能确定，直接结算左指针并右移；右侧对称处理。\n时间 O(n)，空间 O(1)。', 1, 1, 1),
(349, '电话号码的字母组合', '给定一个仅包含数字 2-9 的字符串，返回所有它能表示的字母组合。答案可以按任意顺序返回。\n数字到字母的映射与电话按键相同：2-abc、3-def、4-ghi、5-jkl、6-mno、7-pqrs、8-tuv、9-wxyz。', '一行：仅含数字 2-9 的字符串', '输出所有字母组合，格式如 [\"ad\",\"ae\"]', '23\n', '[\"ad\",\"ae\",\"af\",\"bd\",\"be\",\"bf\",\"cd\",\"ce\",\"cf\"]\n', 'MEDIUM', 15, 1000, 64, '', 'import java.util.*;\n\npublic class Main {\n    static String[] MAP = {\"\", \"\", \"abc\", \"def\", \"ghi\", \"jkl\", \"mno\", \"pqrs\", \"tuv\", \"wxyz\"};\n    static List<String> res = new ArrayList<>();\n\n    static void dfs(String digits, int idx, StringBuilder path) {\n        if (idx == digits.length()) {\n            res.add(path.toString());\n            return;\n        }\n        String letters = MAP[digits.charAt(idx) - \'0\'];\n        for (char c : letters.toCharArray()) {\n            path.append(c);\n            dfs(digits, idx + 1, path);\n            path.deleteCharAt(path.length() - 1);\n        }\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String digits = sc.nextLine().trim();\n        if (!digits.isEmpty()) dfs(digits, 0, new StringBuilder());\n\n        StringBuilder sb = new StringBuilder(\"[\");\n        for (int i = 0; i < res.size(); i++) {\n            if (i > 0) sb.append(\",\");\n            sb.append(\"\\\"\").append(res.get(i)).append(\"\\\"\");\n        }\n        sb.append(\"]\");\n        System.out.println(sb);\n    }\n}\n', '典型的回溯（DFS）：逐位处理数字，把该数字对应的每个字母依次追加到路径上，处理完所有位就把路径加入结果，然后回溯（删掉最后加的字符）。\n注意输入为空时要返回空列表。', 1, 1, 1),
(350, '实现strStr', '给你两个字符串 haystack 和 needle，请你在 haystack 字符串中找出 needle 字符串的第一个匹配项的下标（下标从 0 开始）。\n如果 needle 不是 haystack 的一部分，则返回 -1。\n如果 needle 是空字符串，则返回 0。', '第一行：haystack\n第二行：needle', '输出第一个匹配项的下标，不存在输出 -1', 'sadbutsad\nsad\n', '0\n', 'EASY', 1, 1000, 64, '', 'import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String haystack = sc.nextLine();\n        String needle = sc.nextLine();\n\n        int n = haystack.length(), m = needle.length();\n        if (m == 0) {\n            System.out.println(0);\n            return;\n        }\n        for (int i = 0; i + m <= n; i++) {\n            int j = 0;\n            while (j < m && haystack.charAt(i + j) == needle.charAt(j)) j++;\n            if (j == m) {\n                System.out.println(i);\n                return;\n            }\n        }\n        System.out.println(-1);\n    }\n}\n', '朴素匹配：枚举 haystack 中每个可能的起点，逐字符和 needle 比较，全对就返回该下标。\n复杂度 O(nm)。如果想更快可以用 KMP 算法做到 O(n+m)，但面试里朴素写法的边界处理（空 needle、剩余长度不足）往往才是考点。', 1, 1, 1),
(351, '搜索二维矩阵', '给你一个满足下述两条属性的 m x n 整数矩阵：\n  1. 每行中的整数从左到右按非严格递增顺序排列\n  2. 每行的第一个整数大于前一行的最后一个整数\n给你一个整数 target，如果 target 在矩阵中，返回 true；否则返回 false。', '第一行：行数 m 和列数 n\n接下来 m 行，每行 n 个整数\n最后一行：target', '输出 true 或 false', '3 4\n1 3 5 7\n10 11 16 20\n23 30 34 60\n3\n', 'true\n', 'MEDIUM', 16, 1000, 64, '', 'import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int m = sc.nextInt(), n = sc.nextInt();\n        int[][] matrix = new int[m][n];\n        for (int i = 0; i < m; i++)\n            for (int j = 0; j < n; j++) matrix[i][j] = sc.nextInt();\n        int target = sc.nextInt();\n\n        // 把二维矩阵看成一行长度为 m*n 的有序数组，直接二分\n        int lo = 0, hi = m * n - 1;\n        boolean found = false;\n        while (lo <= hi) {\n            int mid = lo + (hi - lo) / 2;\n            int v = matrix[mid / n][mid % n];\n            if (v == target) { found = true; break; }\n            if (v < target) lo = mid + 1;\n            else hi = mid - 1;\n        }\n        System.out.println(found);\n    }\n}\n', '这两条性质合起来，等价于「把矩阵按行拼接成一个有序数组」。\n所以直接用下标映射做一次二分：mid 对应的元素是 matrix[mid / n][mid % n]。\n时间 O(log(mn))，空间 O(1)。', 1, 1, 1),
(352, '颜色分类', '给定一个包含红色、白色和蓝色、共 n 个元素的数组 nums，原地对它们进行排序，使得相同颜色的元素相邻，并按照红色、白色、蓝色顺序排列。\n我们使用整数 0、1 和 2 分别表示红色、白色和蓝色。\n必须在不使用库内置的 sort 函数的情况下解决这个问题，且只能进行常数级空间操作。', '第一行：数组长度 n\n第二行：n 个整数（只含 0、1、2）', '输出排序后的数组（空格分隔）', '6\n2 0 2 1 1 0\n', '0 0 1 1 2 2\n', 'MEDIUM', 1, 1000, 64, '', 'import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] nums = new int[n];\n        for (int i = 0; i < n; i++) nums[i] = sc.nextInt();\n\n        // 荷兰国旗问题：三指针把数组分成 <1 / =1 / >1 三段\n        int low = 0, mid = 0, high = n - 1;\n        while (mid <= high) {\n            if (nums[mid] == 0) {\n                int t = nums[low]; nums[low] = nums[mid]; nums[mid] = t;\n                low++;\n                mid++;\n            } else if (nums[mid] == 2) {\n                int t = nums[mid]; nums[mid] = nums[high]; nums[high] = t;\n                high--;                 // 换过来的数还没检查，mid 不动\n            } else {\n                mid++;\n            }\n        }\n\n        StringBuilder sb = new StringBuilder();\n        for (int i = 0; i < n; i++) {\n            if (i > 0) sb.append(\" \");\n            sb.append(nums[i]);\n        }\n        System.out.println(sb);\n    }\n}\n', '荷兰国旗（三路快排的 partition）：维护三个指针\n  low  —— 0 区间的右边界\n  mid  —— 当前扫描位置\n  high —— 2 区间的左边界\n遇到 0 与 low 交换并同时推进 low、mid；遇到 2 与 high 交换、只左移 high（换过来的元素还没看过，mid 不能动）；遇到 1 直接 mid++。\n一遍扫描完成，时间 O(n)，空间 O(1)。', 1, 1, 1),
(353, '子集II', '给你一个整数数组 nums，其中可能包含重复元素，请你返回该数组所有可能的子集（幂集）。\n解集不能包含重复的子集。返回的解集中，子集可以按任意顺序排列。', '第一行：数组长度 n\n第二行：n 个整数', '输出所有子集，格式如 [[],[1],[1,2],[2]]', '3\n1 2 2\n', '[[],[1],[1,2],[1,2,2],[2],[2,2]]\n', 'MEDIUM', 15, 1000, 64, '', 'import java.util.*;\n\npublic class Main {\n    static List<List<Integer>> res = new ArrayList<>();\n\n    static void dfs(int[] nums, int start, List<Integer> path) {\n        res.add(new ArrayList<>(path));\n        for (int i = start; i < nums.length; i++) {\n            // 同一层里跳过重复元素，避免产生重复子集\n            if (i > start && nums[i] == nums[i - 1]) continue;\n            path.add(nums[i]);\n            dfs(nums, i + 1, path);\n            path.remove(path.size() - 1);\n        }\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] nums = new int[n];\n        for (int i = 0; i < n; i++) nums[i] = sc.nextInt();\n        Arrays.sort(nums);   // 排序后重复元素相邻，才方便跳过\n\n        dfs(nums, 0, new ArrayList<>());\n\n        StringBuilder sb = new StringBuilder(\"[\");\n        for (int i = 0; i < res.size(); i++) {\n            if (i > 0) sb.append(\",\");\n            sb.append(\"[\");\n            List<Integer> one = res.get(i);\n            for (int j = 0; j < one.size(); j++) {\n                if (j > 0) sb.append(\",\");\n                sb.append(one.get(j));\n            }\n            sb.append(\"]\");\n        }\n        sb.append(\"]\");\n        System.out.println(sb);\n    }\n}\n', '回溯 + 去重：\n  1. 先排序，让相同的元素挨在一起；\n  2. DFS 时每一层用一个 start 控制可选的起点，每个节点都是一个合法子集；\n  3. 去重关键：在同一层里，如果 nums[i] == nums[i-1] 且 i > start，就跳过。\n注意是「同一层」去重（i > start），而不是全局去重。', 1, 1, 1),
(354, '解码方法', '一条包含字母 A-Z 的消息通过以下映射进行了编码：\'A\' -> 1、\'B\' -> 2、…、\'Z\' -> 26。\n要解码已编码的消息，所有数字必须基于上述映射的方法，反向映射回字母。\n给你一个只含数字的非空字符串 s，请计算并返回解码方法的总数。', '一行：数字字符串 s', '输出解码方法总数', '226\n', '3\n', 'MEDIUM', 13, 1000, 64, '', 'import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String s = sc.nextLine().trim();\n        int n = s.length();\n\n        // dp[i] 表示前 i 个字符的解码方法数\n        int[] dp = new int[n + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= n; i++) {\n            // 单个数字 1-9 可以单独解码\n            if (s.charAt(i - 1) != \'0\') dp[i] += dp[i - 1];\n            // 两个数字在 10-26 之间可以合并解码\n            if (i >= 2) {\n                int two = (s.charAt(i - 2) - \'0\') * 10 + (s.charAt(i - 1) - \'0\');\n                if (two >= 10 && two <= 26) dp[i] += dp[i - 2];\n            }\n        }\n        System.out.println(dp[n]);\n    }\n}\n', '线性 DP。dp[i] 表示前 i 个字符的解码方法数，dp[0] = 1：\n  最后一个字符单独解码：若它不为 \'0\'，则 dp[i] += dp[i-1]；\n  最后两个字符合并解码：若数值在 [10, 26] 之间，则 dp[i] += dp[i-2]。\n注意 \'0\' 不能单独解码，必须和前一位组合。', 1, 1, 1),
(355, '不同的二叉搜索树', '给你一个整数 n，求恰由 n 个节点组成且节点值从 1 到 n 互不相同的二叉搜索树有多少种？\n返回满足题意的二叉搜索树的种数。', '一行：整数 n', '输出二叉搜索树的种数', '3\n', '5\n', 'MEDIUM', 13, 1000, 64, '', 'import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n\n        // dp[i]：i 个节点能组成多少种 BST。枚举根节点后左右子树的组合数相乘再求和。\n        long[] dp = new long[n + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= n; i++) {\n            for (int left = 0; left < i; left++) {\n                dp[i] += dp[left] * dp[i - 1 - left];\n            }\n        }\n        System.out.println(dp[n]);\n    }\n}\n', '这是卡特兰数。设 dp[i] 表示 i 个节点能构成的 BST 种数：\n  枚举根节点，假设左子树有 left 个节点，则右子树有 i-1-left 个；\n  dp[i] = Σ dp[left] × dp[i-1-left]，其中 left 从 0 到 i-1；\n  dp[0] = dp[1] = 1。\n结果注意用 long（n 稍大就会溢出 int）。', 1, 1, 1),
(356, '三角形最小路径和', '给定一个三角形 triangle，找出自顶向下的最小路径和。\n每一步只能移动到下一行中相邻的结点上（下标相同或下标 +1）。', '第一行：三角形行数 n\n接下来 n 行，第 i 行有 i 个整数', '输出自顶向下的最小路径和', '4\n2\n3 4\n6 5 7\n4 1 8 3\n', '11\n', 'MEDIUM', 13, 1000, 64, '', 'import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[][] tri = new int[n][];\n        for (int i = 0; i < n; i++) {\n            tri[i] = new int[i + 1];\n            for (int j = 0; j <= i; j++) tri[i][j] = sc.nextInt();\n        }\n\n        // 从倒数第二行往上推：dp[j] = tri[i][j] + min(下方两个)\n        int[] dp = tri[n - 1].clone();\n        for (int i = n - 2; i >= 0; i--) {\n            for (int j = 0; j <= i; j++) {\n                dp[j] = tri[i][j] + Math.min(dp[j], dp[j + 1]);\n            }\n        }\n        System.out.println(dp[0]);\n    }\n}\n', '自底向上的 DP：从倒数第二行开始，每个位置的最小路径和 = 自身值 + 下方两个相邻位置中较小的那个。\n  用一维数组滚动即可：dp[j] = tri[i][j] + min(dp[j], dp[j+1])\n最后 dp[0] 就是答案。时间 O(n²)，空间 O(n)。', 1, 1, 1),
(357, '单词拆分', '给你一个字符串 s 和一个字符串列表 wordDict 作为字典。\n如果可以利用字典中出现的一个或多个单词拼接出 s，则返回 true。\n注意：不要求字典中出现的单词全部都使用，并且字典中的单词可以重复使用。', '第一行：字符串 s\n第二行：字典单词个数 n\n接下来 n 行，每行一个单词', '输出 true 或 false', 'leetcode\n2\nleet\ncode\n', 'true\n', 'MEDIUM', 13, 1000, 64, '', 'import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String s = sc.nextLine().trim();\n        int n = Integer.parseInt(sc.nextLine().trim());\n        Set<String> dict = new HashSet<>();\n        for (int i = 0; i < n; i++) dict.add(sc.nextLine().trim());\n\n        // dp[i] 表示 s 的前 i 个字符能否被字典拼出来\n        boolean[] dp = new boolean[s.length() + 1];\n        dp[0] = true;\n        for (int i = 1; i <= s.length(); i++) {\n            for (int j = 0; j < i; j++) {\n                if (dp[j] && dict.contains(s.substring(j, i))) {\n                    dp[i] = true;\n                    break;\n                }\n            }\n        }\n        System.out.println(dp[s.length()]);\n    }\n}\n', '令 dp[i] 表示 s 的前 i 个字符能否由字典拼出，dp[0] = true。\n对每个 i，枚举切分点 j：若 dp[j] 为真且 s[j..i) 在字典里，则 dp[i] 为真。\n时间 O(n²·L)（L 为子串比较开销），空间 O(n)。\n也可以改用字典树（Trie）优化枚举。', 1, 1, 1),
(358, '前K个高频元素', '给你一个整数数组 nums 和一个整数 k，请你返回其中出现频率前 k 高的元素。\n你可以按任意顺序返回答案。若频率相同，则数值较小的排在前面（用于保证输出唯一）。', '第一行：数组长度 n 和整数 k\n第二行：n 个整数', '输出前 k 个高频元素，格式为 [a,b]', '6 2\n1 1 1 2 2 3\n', '[1,2]\n', 'MEDIUM', 18, 1000, 64, '', 'import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt(), k = sc.nextInt();\n        Map<Integer, Integer> freq = new HashMap<>();\n        for (int i = 0; i < n; i++) {\n            freq.merge(sc.nextInt(), 1, Integer::sum);\n        }\n\n        // 小顶堆：按「频率升序，频率相同数值大的优先淘汰」，堆里保持 k 个\n        PriorityQueue<int[]> heap = new PriorityQueue<>((a, b) ->\n                a[1] != b[1] ? a[1] - b[1] : b[0] - a[0]);\n        for (Map.Entry<Integer, Integer> e : freq.entrySet()) {\n            heap.offer(new int[]{e.getKey(), e.getValue()});\n            if (heap.size() > k) heap.poll();\n        }\n\n        List<int[]> list = new ArrayList<>(heap);\n        // 最终按「频率降序，频率相同数值升序」输出\n        list.sort((a, b) -> a[1] != b[1] ? b[1] - a[1] : a[0] - b[0]);\n        StringBuilder sb = new StringBuilder(\"[\");\n        for (int i = 0; i < list.size(); i++) {\n            if (i > 0) sb.append(\",\");\n            sb.append(list.get(i)[0]);\n        }\n        sb.append(\"]\");\n        System.out.println(sb);\n    }\n}\n', '两步：\n  1. 用哈希表统计每个元素的出现次数；\n  2. 维护一个大小为 k 的小顶堆，堆里存 [元素, 频次]，按频次比较；新元素入堆后若超过 k 就弹出堆顶（频次最低的）。\n时间 O(n log k)，比全排序 O(n log n) 更优。', 1, 1, 1),
(359, '字符串解码', '给定一个经过编码的字符串，返回它解码后的字符串。\n编码规则为: k[encoded_string]，表示其中方括号内部的 encoded_string 正好重复 k 次。\n注意 k 保证为正整数，输入字符串总是有效的，没有额外的空格，且方括号总是格式正确的。\n另外，你可以认为原始数据不包含数字，所有的数字只表示重复次数 k。', '一行：编码后的字符串', '输出解码后的字符串', '3[a]2[bc]\n', 'aaabcbc\n', 'MEDIUM', 1, 1000, 64, '', 'import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String s = sc.nextLine().trim();\n\n        Deque<Integer> numStack = new ArrayDeque<>();\n        Deque<StringBuilder> strStack = new ArrayDeque<>();\n        StringBuilder cur = new StringBuilder();\n        int num = 0;\n\n        for (char c : s.toCharArray()) {\n            if (Character.isDigit(c)) {\n                num = num * 10 + (c - \'0\');\n            } else if (c == \'[\') {\n                numStack.push(num);\n                strStack.push(cur);\n                num = 0;\n                cur = new StringBuilder();\n            } else if (c == \']\') {\n                int repeat = numStack.pop();\n                StringBuilder prev = strStack.pop();\n                for (int i = 0; i < repeat; i++) prev.append(cur);\n                cur = prev;\n            } else {\n                cur.append(c);\n            }\n        }\n        System.out.println(cur);\n    }\n}\n', '双栈法：一个栈存重复次数，一个栈存「进入括号前的已解码字符串」。\n  遇到数字：累积到 num（可能多位）；\n  遇到 \'[\'：把 num 和当前字符串分别压栈，然后重置这两个变量；\n  遇到 \']\'：弹出次数和之前的字符串，把当前字符串重复 num 次后接回去；\n  遇到字母：追加到当前字符串。', 1, 1, 1),
(360, '分割等和子集', '给你一个只包含正整数的非空数组 nums。请你判断是否可以将这个数组分割成两个子集，使得两个子集的元素和相等。', '第一行：数组长度 n\n第二行：n 个正整数', '输出 true 或 false', '4\n1 5 11 5\n', 'true\n', 'MEDIUM', 13, 1000, 64, '', 'import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] nums = new int[n];\n        int sum = 0;\n        for (int i = 0; i < n; i++) {\n            nums[i] = sc.nextInt();\n            sum += nums[i];\n        }\n        if (sum % 2 != 0) {\n            System.out.println(false);\n            return;\n        }\n\n        // 0/1 背包：能否凑出 sum/2\n        int target = sum / 2;\n        boolean[] dp = new boolean[target + 1];\n        dp[0] = true;\n        for (int v : nums) {\n            // 逆序遍历，保证每个数只用一次\n            for (int j = target; j >= v; j--) {\n                dp[j] = dp[j] || dp[j - v];\n            }\n        }\n        System.out.println(dp[target]);\n    }\n}\n', '本质是 0/1 背包：把问题转成「能否从数组里选出若干个数，使其和等于总和的一半」。\n  总和为奇数直接返回 false；\n  令 dp[j] 表示能否凑出和 j，dp[0] = true；\n  对每个数字，容量 j 从大到小逆序遍历（保证每个数只用一次）：dp[j] |= dp[j-v]。\n时间 O(n·target)。', 1, 1, 1),
(361, '寻找重复数', '给定一个包含 n + 1 个整数的数组 nums，其数字都在 [1, n] 范围内（包括 1 和 n），可知至少存在一个重复的整数。\n假设 nums 只有一个重复的整数，返回这个重复的数。\n要求不修改数组 nums，且只用常量级 O(1) 的额外空间。', '第一行：n\n第二行：n+1 个整数', '输出重复的那个数', '4\n1 3 4 2 2\n', '2\n', 'MEDIUM', 1, 1000, 64, '', 'import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] nums = new int[n + 1];\n        for (int i = 0; i <= n; i++) nums[i] = sc.nextInt();\n\n        // 把下标当作节点、nums[i] 当作 next 指针，重复的数就是环的入口\n        int slow = nums[0], fast = nums[0];\n        do {\n            slow = nums[slow];\n            fast = nums[nums[fast]];\n        } while (slow != fast);\n\n        slow = nums[0];\n        while (slow != fast) {\n            slow = nums[slow];\n            fast = nums[fast];\n        }\n        System.out.println(slow);\n    }\n}\n', '把数组看成链表：下标 i 指向 nums[i]。因为存在重复数字，一定形成环，且环的入口就是重复的那个数。\n于是问题变成「找链表入环点」——快慢指针（Floyd 判圈）：\n  1. 快慢指针相遇；\n  2. 一个指针回到起点，两个指针同速前进，再次相遇处即入环点。\n时间 O(n)，空间 O(1)，且不修改数组。', 1, 1, 1),
(362, '完全平方数', '给你一个整数 n，返回和为 n 的完全平方数的最少数量。\n完全平方数是一个整数，其值等于另一个整数的平方；换句话说，其值等于一个整数自乘的积。\n例如，1、4、9 和 16 都是完全平方数，而 3 和 11 不是。', '一行：整数 n', '输出最少数量', '12\n', '3\n', 'MEDIUM', 13, 1000, 64, '', 'import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n\n        // dp[i]：组成 i 所需的最少完全平方数个数（完全背包，物品可重复使用）\n        int[] dp = new int[n + 1];\n        Arrays.fill(dp, Integer.MAX_VALUE);\n        dp[0] = 0;\n        for (int i = 1; i <= n; i++) {\n            for (int j = 1; j * j <= i; j++) {\n                dp[i] = Math.min(dp[i], dp[i - j * j] + 1);\n            }\n        }\n        System.out.println(dp[n]);\n    }\n}\n', '完全背包 + 求最小个数：\n  dp[i] 表示凑出 i 需要的最少平方数个数，dp[0] = 0；\n  对每个 i，枚举所有不超过 i 的平方数 j²：dp[i] = min(dp[i], dp[i - j²] + 1)。\n时间 O(n√n)。数论上还有四平方和定理，可以做到 O(√n) 的特判解法。', 1, 1, 1),
(363, '最长回文子序列', '给你一个字符串 s，找出其中最长的回文子序列，并返回该序列的长度。\n子序列定义为：不改变剩余字符顺序的情况下，删除某些字符或者不删除任何字符形成的一个序列。', '一行：字符串 s', '输出最长回文子序列的长度', 'bbbab\n', '4\n', 'MEDIUM', 13, 1000, 64, '', 'import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String s = sc.nextLine().trim();\n        int n = s.length();\n\n        // dp[i][j]：s[i..j] 的最长回文子序列长度\n        int[][] dp = new int[n][n];\n        for (int i = 0; i < n; i++) dp[i][i] = 1;\n        for (int len = 2; len <= n; len++) {\n            for (int i = 0; i + len - 1 < n; i++) {\n                int j = i + len - 1;\n                if (s.charAt(i) == s.charAt(j)) {\n                    dp[i][j] = dp[i + 1][j - 1] + 2;\n                } else {\n                    dp[i][j] = Math.max(dp[i + 1][j], dp[i][j - 1]);\n                }\n            }\n        }\n        System.out.println(dp[0][n - 1]);\n    }\n}\n', '区间 DP。dp[i][j] 表示子串 s[i..j] 的最长回文子序列长度：\n  若 s[i] == s[j]：dp[i][j] = dp[i+1][j-1] + 2；\n  否则：dp[i][j] = max(dp[i+1][j], dp[i][j-1])。\n按区间长度从小到大递推。注意子序列可以跳过字符，这和「最长回文子串」要求连续是不同的。', 1, 1, 1),
(364, '两个数组的交集II', '给你两个整数数组 nums1 和 nums2，请你以数组形式返回两数组的交集。\n返回结果中每个元素出现的次数，应与元素在两个数组中都出现的次数一致（即取较小值）。\n可以不考虑输出结果的顺序，本题要求按升序输出以便判题。', '第一行：nums1 的长度\n第二行：nums1 的元素\n第三行：nums2 的长度\n第四行：nums2 的元素', '输出交集，按升序，格式为 [a,b]', '4\n4 9 5 9\n5\n9 4 9 8 4\n', '[4,9,9]\n', 'EASY', 1, 1000, 64, '', 'import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n1 = sc.nextInt();\n        Map<Integer, Integer> count = new HashMap<>();\n        for (int i = 0; i < n1; i++) {\n            count.merge(sc.nextInt(), 1, Integer::sum);\n        }\n        int n2 = sc.nextInt();\n        List<Integer> res = new ArrayList<>();\n        for (int i = 0; i < n2; i++) {\n            int v = sc.nextInt();\n            Integer c = count.get(v);\n            if (c != null && c > 0) {\n                res.add(v);\n                count.put(v, c - 1);\n            }\n        }\n        Collections.sort(res);\n\n        StringBuilder sb = new StringBuilder(\"[\");\n        for (int i = 0; i < res.size(); i++) {\n            if (i > 0) sb.append(\",\");\n            sb.append(res.get(i));\n        }\n        sb.append(\"]\");\n        System.out.println(sb);\n    }\n}\n', '哈希计数法：先统计 nums1 中每个元素的出现次数，再遍历 nums2 —— 遇到计数 > 0 的元素就加入结果并把计数减 1（这样就自动取了两个数组中出现次数的较小值）。\n时间 O(n+m)。如果两个数组已经有序，还可以用双指针做到 O(n+m) 且不用额外空间。', 1, 2, 1),
(365, '两数相加', '给你两个非空的链表，表示两个非负的整数。它们每位数字都是按照逆序的方式存储的，并且每个节点只能存储一位数字。\n请你将两个数相加，并以相同形式返回一个表示和的链表。\n你可以假设除了数字 0 之外，这两个数都不会以 0 开头。', '第一行：链表1，格式如 2->4->3->NULL\n第二行：链表2，格式如 5->6->4->NULL', '输出相加后的链表，格式如 7->0->8->NULL', '2->4->3->NULL\n5->6->4->NULL\n', '7->0->8->NULL\n', 'MEDIUM', 2, 1000, 64, '', 'import java.util.*;\n\npublic class Main {\n    static class ListNode {\n        int val;\n        ListNode next;\n        ListNode(int v) { val = v; }\n    }\n\n    static ListNode build(String line) {\n        line = line.trim();\n        if (line.endsWith(\"->NULL\")) line = line.substring(0, line.length() - 6);\n        if (line.isEmpty() || \"NULL\".equals(line)) return null;\n        String[] parts = line.split(\"->\");\n        ListNode dummy = new ListNode(0), cur = dummy;\n        for (String s : parts) {\n            cur.next = new ListNode(Integer.parseInt(s.trim()));\n            cur = cur.next;\n        }\n        return dummy.next;\n    }\n\n    static String serialize(ListNode head) {\n        StringBuilder sb = new StringBuilder();\n        while (head != null) {\n            sb.append(head.val).append(\"->\");\n            head = head.next;\n        }\n        sb.append(\"NULL\");\n        return sb.toString();\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        ListNode l1 = build(sc.nextLine());\n        ListNode l2 = build(sc.nextLine());\n\n        ListNode dummy = new ListNode(0), cur = dummy;\n        int carry = 0;\n        while (l1 != null || l2 != null || carry > 0) {\n            int x = l1 != null ? l1.val : 0;\n            int y = l2 != null ? l2.val : 0;\n            int sum = x + y + carry;\n            cur.next = new ListNode(sum % 10);\n            cur = cur.next;\n            carry = sum / 10;\n            if (l1 != null) l1 = l1.next;\n            if (l2 != null) l2 = l2.next;\n        }\n        System.out.println(serialize(dummy.next));\n    }\n}\n', '因为链表本身就是逆序存储（个位在头），所以可以从头开始逐位相加，正好对应竖式加法。\n  每轮取两个链表当前位（为空当 0），加上进位得到 sum；\n  当前位结果是 sum % 10，新进位是 sum / 10；\n  循环条件要包含 carry > 0，否则最高位进位会丢。\n用哑节点简化结果链表的构造。', 1, 1, 1),
(366, '最长连续序列', '给定一个未排序的整数数组 nums，找出数字连续的最长序列（不要求序列元素在原数组中连续）的长度。\n请你设计并实现时间复杂度为 O(n) 的算法解决此问题。', '第一行：数组长度 n\n第二行：n 个整数', '输出最长连续序列的长度', '6\n100 4 200 1 3 2\n', '4\n', 'MEDIUM', 1, 1000, 64, '', 'import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        Set<Integer> set = new HashSet<>();\n        for (int i = 0; i < n; i++) set.add(sc.nextInt());\n\n        int best = 0;\n        for (int v : set) {\n            // 只从「连续段的起点」开始数：v-1 不存在说明它是起点\n            if (set.contains(v - 1)) continue;\n            int cur = v;\n            int len = 1;\n            while (set.contains(cur + 1)) {\n                cur++;\n                len++;\n            }\n            best = Math.max(best, len);\n        }\n        System.out.println(best);\n    }\n}\n', '全部数字放进 HashSet（去重 + O(1) 查询）。\n关键优化：只对「连续段的起点」做扩展 —— 如果 v-1 也在集合里，说明 v 不是起点，直接跳过。\n这样每个数字最多被访问两次，总复杂度 O(n)，否则退化成 O(n²)。', 1, 1, 1),
(367, '合并两个有序数组', '给你两个按非递减顺序排列的整数数组 nums1 和 nums2，另有两个整数 m 和 n，分别表示 nums1 和 nums2 中的元素数目。\n请你合并 nums2 到 nums1 中，使合并后的数组同样按非递减顺序排列。\n注意：最终合并后数组不应由函数返回，而是存储在数组 nums1 中。', '第一行：m 和 n\n第二行：nums1 的 m 个元素\n第三行：nums2 的 n 个元素', '输出合并后的数组（m+n 个元素，空格分隔）', '3 3\n1 2 3\n2 5 6\n', '1 2 2 3 5 6\n', 'EASY', 1, 1000, 64, '', 'import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int m = sc.nextInt(), n = sc.nextInt();\n        int[] nums1 = new int[m + n];\n        for (int i = 0; i < m; i++) nums1[i] = sc.nextInt();\n        int[] nums2 = new int[n];\n        for (int i = 0; i < n; i++) nums2[i] = sc.nextInt();\n\n        // 从后往前填，避免覆盖 nums1 中还没比较的元素\n        int i = m - 1, j = n - 1, k = m + n - 1;\n        while (j >= 0) {\n            if (i >= 0 && nums1[i] > nums2[j]) {\n                nums1[k--] = nums1[i--];\n            } else {\n                nums1[k--] = nums2[j--];\n            }\n        }\n\n        StringBuilder sb = new StringBuilder();\n        for (int t = 0; t < m + n; t++) {\n            if (t > 0) sb.append(\" \");\n            sb.append(nums1[t]);\n        }\n        System.out.println(sb);\n    }\n}\n', '双指针 + 从后往前：\nnums1 的后半部分是空的（预留了 m+n 的长度），所以可以从最大的位置（下标 m+n-1）倒着填。\n每次比较两个数组当前的最后一个元素，把大的放到末尾。\n从后往前写可以避免把 nums1 还没比较的元素覆盖掉；循环只需判断 j >= 0，因为 nums2 填完后 nums1 剩下的部分本来就已经有序。', 1, 1, 1),
(368, '螺旋矩阵II', '给你一个正整数 n，生成一个包含 1 到 n² 所有元素，且元素按顺时针顺序螺旋排列的 n x n 正方形矩阵 matrix。', '一行：正整数 n', '输出 n 行，每行 n 个整数（空格分隔）', '3\n', '1 2 3\n8 9 4\n7 6 5\n', 'MEDIUM', 1, 1000, 64, '', 'import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[][] m = new int[n][n];\n\n        int top = 0, bottom = n - 1, left = 0, right = n - 1;\n        int val = 1;\n        while (top <= bottom && left <= right) {\n            for (int j = left; j <= right; j++) m[top][j] = val++;\n            top++;\n            for (int i = top; i <= bottom; i++) m[i][right] = val++;\n            right--;\n            if (top <= bottom) {\n                for (int j = right; j >= left; j--) m[bottom][j] = val++;\n                bottom--;\n            }\n            if (left <= right) {\n                for (int i = bottom; i >= top; i--) m[i][left] = val++;\n                left++;\n            }\n        }\n\n        StringBuilder sb = new StringBuilder();\n        for (int i = 0; i < n; i++) {\n            for (int j = 0; j < n; j++) {\n                if (j > 0) sb.append(\" \");\n                sb.append(m[i][j]);\n            }\n            sb.append(\"\\n\");\n        }\n        System.out.print(sb);\n    }\n}\n', '按四条边界模拟：top / bottom / left / right 分别表示当前未填充区域的上、下、左、右边界。\n依次填充「上边一行 → 右边一列 → 下边一行 → 左边一列」，每填完一条边就把对应边界收缩一格。\n注意下面两条边要加 if 判断，否则在只剩一行/一列时会重复填充。', 1, 1, 1),
(369, '跳跃游戏II', '给定一个长度为 n 的 0 索引整数数组 nums。初始位置为 nums[0]。\n每个元素 nums[i] 表示从索引 i 向前跳转的最大长度。换句话说，如果你在 nums[i] 处，你可以跳转到任意 nums[i + j] 处（0 <= j <= nums[i] 且 i + j < n）。\n返回到达 nums[n-1] 的最小跳跃次数。生成的测试用例可以到达 nums[n-1]。', '第一行：数组长度 n\n第二行：n 个非负整数', '输出最小跳跃次数', '5\n2 3 1 1 4\n', '2\n', 'MEDIUM', 14, 1000, 64, '', 'import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] nums = new int[n];\n        for (int i = 0; i < n; i++) nums[i] = sc.nextInt();\n\n        // 贪心：把每一跳能覆盖的范围看成一段，跳一次就进入下一段\n        int jumps = 0, curEnd = 0, farthest = 0;\n        for (int i = 0; i < n - 1; i++) {\n            farthest = Math.max(farthest, i + nums[i]);\n            if (i == curEnd) {          // 走到了当前这一跳的边界，必须再跳一次\n                jumps++;\n                curEnd = farthest;\n            }\n        }\n        System.out.println(jumps);\n    }\n}\n', '贪心（按层推进）：维护三个量\n  farthest —— 当前能到达的最远位置\n  curEnd   —— 当前这一跳的覆盖边界\n  jumps    —— 已跳次数\n遍历数组（不含最后一个元素）：不断更新 farthest；当 i 走到 curEnd 时说明这一跳的覆盖范围用尽了，必须再跳一次（jumps++）并把 curEnd 推进到 farthest。\n时间 O(n)，空间 O(1)。', 1, 1, 1),
(370, '求众数II', '给定一个大小为 n 的整数数组，找出其中所有出现超过 ⌊n/3⌋ 次的元素。', '第一行：数组长度 n\n第二行：n 个整数', '输出所有满足条件的元素，按升序，格式为 [a,b]；没有则输出 []', '3\n3 2 3\n', '[3]\n', 'MEDIUM', 1, 1000, 64, '', 'import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] nums = new int[n];\n        for (int i = 0; i < n; i++) nums[i] = sc.nextInt();\n\n        // 摩尔投票扩展版：出现超过 n/3 的元素最多有两个，所以维护两个候选\n        int c1 = 0, c2 = 1, cnt1 = 0, cnt2 = 0;\n        for (int v : nums) {\n            if (cnt1 > 0 && v == c1) cnt1++;\n            else if (cnt2 > 0 && v == c2) cnt2++;\n            else if (cnt1 == 0) { c1 = v; cnt1 = 1; }\n            else if (cnt2 == 0) { c2 = v; cnt2 = 1; }\n            else { cnt1--; cnt2--; }\n        }\n        // 投票只能筛出候选，还要再数一遍确认\n        cnt1 = 0; cnt2 = 0;\n        for (int v : nums) {\n            if (v == c1) cnt1++;\n            else if (v == c2) cnt2++;\n        }\n        List<Integer> res = new ArrayList<>();\n        if (cnt1 > n / 3) res.add(c1);\n        if (cnt2 > n / 3) res.add(c2);\n        Collections.sort(res);\n\n        StringBuilder sb = new StringBuilder(\"[\");\n        for (int i = 0; i < res.size(); i++) {\n            if (i > 0) sb.append(\",\");\n            sb.append(res.get(i));\n        }\n        sb.append(\"]\");\n        System.out.println(sb);\n    }\n}\n', '摩尔投票的扩展：出现次数超过 n/3 的元素最多只有 2 个，所以同时维护两组「候选 + 计数」。\n遇到与任一候选相同的就给它计数 +1；计数为 0 就换候选；都不匹配就两个计数各减 1。\n注意投票结束后必须再遍历一次数组核对真实频次 —— 投票只能筛出候选，不能保证达标。', 1, 1, 1),
(371, '生命游戏', '给定一个包含 m × n 个格子的面板，每一个格子都可以看成是一个细胞。每个细胞都有一个初始状态：1 为活细胞，0 为死细胞。\n每个细胞与其八个相邻位置的细胞互动，遵循以下生存定律：\n  1. 活细胞的周围有少于两个活细胞，该细胞死亡（人口过少）\n  2. 活细胞的周围有两个或三个活细胞，该细胞继续存活\n  3. 活细胞的周围有超过三个活细胞，该细胞死亡（人口过多）\n  4. 死细胞的周围有正好三个活细胞，该细胞复活（繁殖）\n请你原地计算面板的下一个状态。', '第一行：行数 m 和列数 n\n接下来 m 行，每行一个长度为 n 的 01 字符串', '输出下一状态的 m 行 01 字符串', '4 3\n010\n001\n111\n000\n', '000\n101\n011\n010\n', 'MEDIUM', 1, 1000, 64, '', 'import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int m = sc.nextInt(), n = sc.nextInt();\n        int[][] b = new int[m][n];\n        for (int i = 0; i < m; i++) {\n            String row = sc.next();\n            for (int j = 0; j < n; j++) b[i][j] = row.charAt(j) - \'0\';\n        }\n\n        // 用「第二位」记录新状态，原地更新：原状态 1 保留在最低位\n        int[] dx = {-1, -1, -1, 0, 0, 1, 1, 1};\n        int[] dy = {-1, 0, 1, -1, 1, -1, 0, 1};\n        for (int i = 0; i < m; i++) {\n            for (int j = 0; j < n; j++) {\n                int live = 0;\n                for (int d = 0; d < 8; d++) {\n                    int x = i + dx[d], y = j + dy[d];\n                    if (x >= 0 && x < m && y >= 0 && y < n) live += (b[x][y] & 1);\n                }\n                int cur = b[i][j] & 1;\n                int next = 0;\n                if (cur == 1 && (live == 2 || live == 3)) next = 1;\n                if (cur == 0 && live == 3) next = 1;\n                b[i][j] |= (next << 1);\n            }\n        }\n\n        StringBuilder sb = new StringBuilder();\n        for (int i = 0; i < m; i++) {\n            for (int j = 0; j < n; j++) sb.append((b[i][j] >> 1) & 1);\n            sb.append(\"\\n\");\n        }\n        System.out.print(sb);\n    }\n}\n', '难点在「原地」更新：如果直接改，后面的格子会读到已经变过的新值。\n技巧是用二进制位打包新旧状态：最低位存原状态，第二位存新状态。\n  读邻居时只取最低位（& 1）保证用的是原状态；\n  写新状态时 |= (next << 1)；\n  最后统一右移一位输出。\n这样只需一次遍历，空间 O(1)。', 1, 1, 1),
(372, '基本计算器II', '给你一个字符串表达式 s，请你实现一个基本计算器来计算并返回它的值。\n整数除法仅保留整数部分（向零取整）。\n表达式仅包含非负整数、+ - * / 四种运算符和空格，且保证是一个有效的表达式。', '一行：表达式字符串（可含空格）', '输出计算结果', '3+2*2\n', '7\n', 'MEDIUM', 1, 1000, 64, '', 'import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String s = sc.nextLine().replace(\" \", \"\");\n\n        Deque<Long> stack = new ArrayDeque<>();\n        char sign = \'+\';\n        long num = 0;\n        for (int i = 0; i < s.length(); i++) {\n            char c = s.charAt(i);\n            if (Character.isDigit(c)) {\n                num = num * 10 + (c - \'0\');\n            }\n            // 遇到运算符或走到末尾，就结算「前一个运算符 + 当前数字」\n            if (!Character.isDigit(c) || i == s.length() - 1) {\n                if (sign == \'+\') {\n                    stack.push(num);\n                } else if (sign == \'-\') {\n                    stack.push(-num);\n                } else if (sign == \'*\') {\n                    stack.push(stack.pop() * num);\n                } else {\n                    stack.push(stack.pop() / num);\n                }\n                sign = c;\n                num = 0;\n            }\n        }\n\n        long sum = 0;\n        while (!stack.isEmpty()) sum += stack.pop();\n        System.out.println(sum);\n    }\n}\n', '把表达式当成「若干项相加」，项由 + - 拆分，乘法除法则即时结算：\n  用一个栈存每一项的值；\n  sign 记录上一个运算符，num 累积当前数字；\n  遇到新运算符（或走到末尾）时，根据 sign 决定：+ 直接入栈、- 入栈相反数、* 和 / 则和栈顶元素就地运算后替换。\n  最后把栈里所有元素求和。乘除的优先级就是通过「就地结算」实现的。', 1, 1, 1),
(373, '数组中的逆序对', '在数组中的两个数字，如果前面一个数字大于后面的数字，则这两个数字组成一个逆序对。\n输入一个数组，求出这个数组中的逆序对的总数。', '第一行：数组长度 n\n第二行：n 个整数', '输出逆序对总数', '4\n7 5 6 4\n', '5\n', 'HARD', 1, 1000, 64, '', 'import java.util.*;\n\npublic class Main {\n    static long count = 0;\n    static int[] tmp;\n\n    // 归并排序过程中统计逆序对\n    static void mergeSort(int[] a, int l, int r) {\n        if (l >= r) return;\n        int mid = (l + r) / 2;\n        mergeSort(a, l, mid);\n        mergeSort(a, mid + 1, r);\n\n        int i = l, j = mid + 1, k = l;\n        while (i <= mid && j <= r) {\n            if (a[i] <= a[j]) {\n                tmp[k++] = a[i++];\n            } else {\n                // a[j] 比 a[i..mid] 都小，这些全都构成逆序对\n                count += mid - i + 1;\n                tmp[k++] = a[j++];\n            }\n        }\n        while (i <= mid) tmp[k++] = a[i++];\n        while (j <= r) tmp[k++] = a[j++];\n        for (int t = l; t <= r; t++) a[t] = tmp[t];\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] a = new int[n];\n        for (int i = 0; i < n; i++) a[i] = sc.nextInt();\n        tmp = new int[n];\n        mergeSort(a, 0, n - 1);\n        System.out.println(count);\n    }\n}\n', '用归并排序统计：在合并两个有序子数组时，若右半边的 a[j] 小于左半边的 a[i]，那么 a[i..mid] 这 mid-i+1 个元素都比 a[j] 大，各自与 a[j] 构成一个逆序对。\n累加这些数量即可，总复杂度 O(n log n)，比暴力 O(n²) 快得多。\n注意计数可能很大，Java 里要用 long。', 1, 1, 1),
(374, '最小的k个数', '输入整数数组 arr，找出其中最小的 k 个数。\n例如输入 4、5、1、6、2、7、3、8 这 8 个数字，则最小的 4 个数字是 1、2、3、4。', '第一行：数组长度 n 和整数 k\n第二行：n 个整数', '输出最小的 k 个数，按升序，各数字用空格分隔', '7 4\n3 2 1 5 6 4 7\n', '1 2 3 4\n', 'EASY', 2, 1000, 64, '', 'import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt(), k = sc.nextInt();\n        int[] arr = new int[n];\n        for (int i = 0; i < n; i++) arr[i] = sc.nextInt();\n\n        // 大顶堆：堆里始终是「当前最小的 k 个」，堆顶是其中最大的\n        PriorityQueue<Integer> heap = new PriorityQueue<>((a, b) -> b - a);\n        for (int v : arr) {\n            if (heap.size() < k) {\n                heap.offer(v);\n            } else if (v < heap.peek()) {\n                heap.poll();\n                heap.offer(v);\n            }\n        }\n\n        List<Integer> res = new ArrayList<>(heap);\n        Collections.sort(res);\n        StringBuilder sb = new StringBuilder();\n        for (int i = 0; i < res.size(); i++) {\n            if (i > 0) sb.append(\" \");\n            sb.append(res.get(i));\n        }\n        System.out.println(sb);\n    }\n}\n', '维护一个大小为 k 的大顶堆：堆里放的就是「目前见过的最小的 k 个数」，堆顶是其中最大的那个。\n新元素如果比堆顶小，就把堆顶弹掉、把它放进去。\n时间 O(n log k)，空间 O(k)，适合 n 很大而 k 很小的场景（比整体排序 O(n log n) 更优）。', 1, 1, 1),
(375, '岛屿的最大面积', '给你一个大小为 m x n 的二进制矩阵 grid。\n岛屿是由一些相邻的 1（代表土地）构成的组合，这里的「相邻」要求两个 1 必须在水平或者竖直的四个方向上相邻。\n岛屿的面积是岛上值为 1 的单元格数目。计算并返回 grid 中最大的岛屿面积。如果没有岛屿，则返回面积为 0。', '第一行：行数 m 和列数 n\n接下来 m 行，每行一个长度为 n 的 01 字符串', '输出最大岛屿面积', '4 5\n11000\n11000\n00100\n00011\n', '4\n', 'MEDIUM', 12, 1000, 64, '', 'import java.util.*;\n\npublic class Main {\n    static int m, n;\n    static int[][] g;\n\n    static int dfs(int i, int j) {\n        if (i < 0 || i >= m || j < 0 || j >= n || g[i][j] != 1) return 0;\n        g[i][j] = 0;      // 淹掉，避免重复访问\n        return 1 + dfs(i - 1, j) + dfs(i + 1, j) + dfs(i, j - 1) + dfs(i, j + 1);\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        m = sc.nextInt();\n        n = sc.nextInt();\n        g = new int[m][n];\n        for (int i = 0; i < m; i++) {\n            String row = sc.next();\n            for (int j = 0; j < n; j++) g[i][j] = row.charAt(j) - \'0\';\n        }\n\n        int best = 0;\n        for (int i = 0; i < m; i++) {\n            for (int j = 0; j < n; j++) {\n                if (g[i][j] == 1) best = Math.max(best, dfs(i, j));\n            }\n        }\n        System.out.println(best);\n    }\n}\n', '遍历每个格子，遇到 1 就以它为起点做 DFS（或 BFS），把连通的 1 全部「淹掉」（置为 0，相当于标记已访问），同时统计这次 DFS 访问了多少个格子，就是该岛屿的面积。\n每个格子最多被访问一次，时间 O(mn)。\n如果要避免递归过深，可以改用显式栈的迭代写法。', 1, 1, 1);
